function escapeHtml(value=''){const span=document.createElement('span');span.textContent=String(value);return span.innerHTML;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600);}
function normalizeContactSearch(value=''){return String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('de-DE').trim();}
function collectContactSearchValues(value,depth=0){if(value===null||value===undefined||depth>3)return[];if(['string','number','boolean'].includes(typeof value))return[String(value)];if(Array.isArray(value))return value.flatMap(item=>collectContactSearchValues(item,depth+1));if(typeof value==='object')return Object.values(value).flatMap(item=>collectContactSearchValues(item,depth+1));return[];}
function globalContactRecords(){
  const participantsById=new Map(participants.map(person=>[person.id,person]));
  const linkedLeadsByParticipant=new Map(leads.filter(lead=>lead.converted_user_profile_id).map(lead=>[lead.converted_user_profile_id,lead]));
  const customerRecords=participants.map(person=>{const linkedLead=linkedLeadsByParticipant.get(person.id)||leads.find(lead=>normalizeContactSearch(lead.email)===normalizeContactSearch(person.email));const phone=linkedLead?.phone||person.phone||'';return{key:`customer:${person.id}`,entityType:'participant',id:person.id,name:person.name,email:person.email,phone,customerNumber:person.customerNumber||'',status:person.week?`Woche ${person.week}`:'Onboarding',typeLabel:'Kunde',searchText:normalizeContactSearch(collectContactSearchValues([person.searchSource||person,linkedLead]).join(' '))};});
  const leadRecords=leads.filter(lead=>!lead.converted_user_profile_id||!participantsById.has(lead.converted_user_profile_id)).map(lead=>{const isCustomer=Boolean(lead.converted_user_profile_id);return{key:`${isCustomer?'customer':'lead'}:${lead.id}`,entityType:isCustomer?'participant':'lead',id:isCustomer?lead.converted_user_profile_id:lead.id,name:lead.name||`${lead.first_name||''} ${lead.last_name||''}`.trim()||'Kontakt ohne Namen',email:lead.email||'',phone:lead.phone||'',customerNumber:lead.customer_number||'',status:leadStatusLabels[lead.status]||lead.status||'Neu',typeLabel:isCustomer?'Kunde':'Interessent',searchText:normalizeContactSearch(collectContactSearchValues(lead).join(' '))};});
  return[...customerRecords,...leadRecords];
}
function globalContactMatches(query){const normalized=normalizeContactSearch(query);if(normalized.length<3)return[];return globalContactRecords().filter(record=>record.searchText.includes(normalized)||normalizeContactSearch(`${record.name} ${record.email} ${record.phone} ${record.customerNumber} ${record.status}`).includes(normalized)).map(record=>{const name=normalizeContactSearch(record.name),email=normalizeContactSearch(record.email),number=normalizeContactSearch(record.customerNumber);const score=name.startsWith(normalized)?0:name.includes(normalized)?1:email.startsWith(normalized)?2:number.startsWith(normalized)?2:3;return{...record,score};}).sort((a,b)=>a.score-b.score||a.name.localeCompare(b.name,'de')).slice(0,8);}
let globalContactSearchSelection=-1;
function closeGlobalContactSearch(){const input=document.querySelector('#globalCrmSearchInput'),results=document.querySelector('#globalCrmSearchResults');if(!input||!results)return;results.hidden=true;results.innerHTML='';input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');globalContactSearchSelection=-1;}
function renderGlobalContactSearch(){const input=document.querySelector('#globalCrmSearchInput'),results=document.querySelector('#globalCrmSearchResults');if(!input||!results)return;const query=input.value.trim();if(normalizeContactSearch(query).length<3)return closeGlobalContactSearch();const matches=globalContactMatches(query);globalContactSearchSelection=Math.min(globalContactSearchSelection,matches.length-1);results.innerHTML=matches.length?matches.map((record,index)=>`<button type="button" role="option" id="global-contact-result-${index}" class="global-contact-result ${index===globalContactSearchSelection?'active':''}" aria-selected="${index===globalContactSearchSelection}" data-global-contact="${escapeHtml(record.key)}"><span class="global-contact-avatar">${escapeHtml(record.name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase()||'?')}</span><span class="global-contact-copy"><strong>${escapeHtml(record.name)}</strong><small>${escapeHtml([record.email,record.phone].filter(Boolean).join(' · ')||'Keine Kontaktdaten hinterlegt')}</small><i>${escapeHtml([record.customerNumber,record.status].filter(Boolean).join(' · '))}</i></span><em class="global-contact-type ${record.entityType}">${escapeHtml(record.typeLabel)}</em><b aria-hidden="true">→</b></button>`).join(''):`<div class="global-contact-empty"><strong>Keine passende Akte gefunden</strong><span>Prüfe Name, E-Mail, Telefon, Kundennummer oder ein anderes Merkmal.</span></div>`;results.hidden=false;input.setAttribute('aria-expanded','true');if(globalContactSearchSelection>=0)input.setAttribute('aria-activedescendant',`global-contact-result-${globalContactSearchSelection}`);else input.removeAttribute('aria-activedescendant');results.querySelectorAll('[data-global-contact]').forEach(button=>button.addEventListener('click',()=>openGlobalContactResult(globalContactRecords().find(record=>record.key===button.dataset.globalContact))));}
async function openGlobalContactResult(record){if(!record)return;const input=document.querySelector('#globalCrmSearchInput');if(input)input.value='';closeGlobalContactSearch();if(record.entityType==='participant'){showView('participants');await openCustomerDashboard(record.id);}else{showView('leads');await openLeadDashboard(record.id);}}
const globalCrmSearch=document.querySelector('#globalCrmSearch'),globalCrmSearchInput=document.querySelector('#globalCrmSearchInput');
globalCrmSearchInput?.addEventListener('input',()=>{globalContactSearchSelection=-1;renderGlobalContactSearch();});
globalCrmSearchInput?.addEventListener('focus',renderGlobalContactSearch);
globalCrmSearchInput?.addEventListener('keydown',event=>{const matches=globalContactMatches(globalCrmSearchInput.value);if(event.key==='Escape'){closeGlobalContactSearch();globalCrmSearchInput.blur();return;}if(!matches.length)return;if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();const direction=event.key==='ArrowDown'?1:-1;globalContactSearchSelection=globalContactSearchSelection<0?(direction>0?0:matches.length-1):(globalContactSearchSelection+direction+matches.length)%matches.length;renderGlobalContactSearch();}else if(event.key==='Enter'){event.preventDefault();openGlobalContactResult(matches[Math.max(0,globalContactSearchSelection)]);}});
document.addEventListener('click',event=>{if(globalCrmSearch&&!globalCrmSearch.contains(event.target))closeGlobalContactSearch();});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();globalCrmSearchInput?.focus();globalCrmSearchInput?.select();}});
function leadNavigationCounts(){const available=leads.filter(lead=>!lead.converted_user_profile_id&&lead.status!=='customer');return{all:available.length,active:available.filter(lead=>!['lost','later'].includes(lead.status)).length,lost:available.filter(lead=>lead.status==='lost').length,later:available.filter(lead=>lead.status==='later').length};}
function contextItemMarkup(item,index){const[title,description,target,settings,mailbox,communicationSection,customerSection]=item;const active=customerSection?(activeCustomerDashboard?customerDashboardPage===customerSection:participantSection===customerSection):index===0;return`<button class="${active?'active':''}" data-context-target="${escapeHtml(target)}" ${settings?`data-context-settings="${escapeHtml(settings)}"`:''} ${mailbox?`data-context-mailbox="${escapeHtml(mailbox)}"`:''} ${communicationSection?`data-context-communication="${escapeHtml(communicationSection)}"`:''} ${customerSection?`data-context-participants="${escapeHtml(customerSection)}"`:''}><span>${String(index+1).padStart(2,'0')}</span><div><b>${escapeHtml(title)}</b><small>${escapeHtml(description)}</small></div></button>`;}
function customerAge(date){if(!date)return'';const birth=new Date(`${date}T00:00:00`),today=new Date();let age=today.getFullYear()-birth.getFullYear();if(today.getMonth()<birth.getMonth()||today.getMonth()===birth.getMonth()&&today.getDate()<birth.getDate())age-=1;return Number.isFinite(age)&&age>=0?`${age} Jahre`:'';}
function customerContextProfileMarkup(){const person=activeCustomerDashboard?.person,profile=activeCustomerDashboard?.customer?.profile||activeCustomerDashboard?.program?.profile||person||{},photo=profile.photoUrl||'';return`<section class="customer-context-profile"><button type="button" class="customer-context-avatar" data-customer-avatar title="Profilbild ändern">${photo?`<img src="${escapeHtml(photo)}" alt="Profilbild von ${escapeHtml(profile.name||'Kunde')}">`:`<span>${escapeHtml(person?.initials||'KD')}</span>`}<i>+</i></button><strong>${escapeHtml(profile.name||'Kundenakte')}</strong><small>${escapeHtml(profile.customer_number||person?.customerNumber||'Kundennummer wird vergeben')}</small>${profile.birth_date?`<em>♙ ${escapeHtml(new Date(`${profile.birth_date}T00:00:00`).toLocaleDateString('de-DE'))}${customerAge(profile.birth_date)?` (${escapeHtml(customerAge(profile.birth_date))})`:''}</em>`:'<em>Geburtsdatum nicht hinterlegt</em>'}</section>`;}
function customerContextGroupsMarkup(config){let index=0;return`${customerContextProfileMarkup()}${config.detailGroups.map(group=>({...group,items:group.items.filter(item=>canAccessCustomerPage(item[6]))})).filter(group=>group.items.length).map(group=>`<section class="customer-context-group"><p>${escapeHtml(group.label)}</p><nav>${group.items.map(item=>contextItemMarkup(item,index++)).join('')}</nav></section>`).join('')}`;}
function renderLeadListContextNavigation(nav,config){const counts=leadNavigationCounts();nav.innerHTML=config.groups.map((group,groupIndex)=>`<section class="lead-context-group"><button type="button" class="lead-context-group-toggle" data-lead-context-group="${groupIndex}" aria-expanded="true"><span>${escapeHtml(group.label)}</span><i>⌄</i></button><div class="lead-context-group-items">${group.items.map(([title,description,filter])=>`<button type="button" class="lead-context-filter ${leadListFilter===filter?'active':''}" data-lead-filter="${escapeHtml(filter)}"><div><b>${escapeHtml(title)}</b><small>${escapeHtml(description)}</small></div>${filter==='all'?'':`<span>${counts[filter]||0}</span>`}</button>`).join('')}</div></section>`).join('');nav.querySelectorAll('[data-lead-context-group]').forEach(button=>button.addEventListener('click',()=>{const expanded=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!expanded));button.closest('.lead-context-group').classList.toggle('collapsed',expanded);}));nav.querySelectorAll('[data-lead-filter]').forEach(button=>button.addEventListener('click',()=>setLeadListFilter(button.dataset.leadFilter)));}
function renderContextNavigation(name){const config=contextNavigation[name]||contextNavigation.command;document.querySelector('#contextIcon').textContent=config.icon;document.querySelector('#contextTitle').textContent=titles[name]||titles.command;const nav=document.querySelector('#contextNav');if(name==='leads'&&!activeLeadDashboard)return renderLeadListContextNavigation(nav,config);if(name==='participants'&&activeCustomerDashboard)nav.innerHTML=customerContextGroupsMarkup(config);else{const configuredItems=name==='leads'?config.detailItems:config.items,items=name==='participants'?configuredItems.filter(item=>canAccessCustomerPage(item[6])):name==='settings'?configuredItems.filter(item=>item[3]!=='users'||activeStaffPermissions.includes('users')):configuredItems;nav.innerHTML=`<p>${escapeHtml(config.label)}</p><nav>${items.map(contextItemMarkup).join('')}</nav>`;}nav.querySelectorAll('[data-context-target]').forEach(button=>button.addEventListener('click',()=>{nav.querySelectorAll('button').forEach(item=>item.classList.toggle('active',item===button));if(button.dataset.contextParticipants){if(activeCustomerDashboard)setCustomerDashboardPage(button.dataset.contextParticipants,false);else setParticipantSection(button.dataset.contextParticipants,false);}if(button.dataset.contextSettings)showSettingsPanel(button.dataset.contextSettings);if(button.dataset.contextCommunication&&typeof setCommunicationSection==='function')setCommunicationSection(button.dataset.contextCommunication,button.dataset.contextMailbox);else if(button.dataset.contextMailbox)setCommunicationFolder(button.dataset.contextMailbox);const target=document.querySelector(`.view.active ${button.dataset.contextTarget}`);target?.scrollIntoView({behavior:'smooth',block:'start'});}));nav.querySelector('[data-customer-avatar]')?.addEventListener('click',()=>document.querySelector('#customerAvatarInput')?.click());}
function showView(name){const isDashboard=name==='command',contextNav=document.querySelector('.context-nav');if(name==='participants')resetCustomerListView();document.body.classList.toggle('dashboard-view',isDashboard);contextNav.hidden=isDashboard;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.dataset.panel===name));document.querySelectorAll('.sidebar nav button[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));document.querySelector('#viewTitle').textContent=titles[name];if(name==='settings')showSettingsPanel('general');if(!isDashboard)renderContextNavigation(name);if(isDashboard)loadCommandDashboard();if(name==='gates')loadGateSettings();if(name==='communications'){loadCommunications();if(typeof loadCommunicationCenter==='function')loadCommunicationCenter();}window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.view==='leads')resetLeadListView();showView(button.dataset.view);}));
document.querySelectorAll('[data-jump]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.jump)));
function showSettingsPanel(name){document.querySelectorAll('[data-settings-panel]').forEach(panel=>panel.classList.toggle('active',panel.dataset.settingsPanel===name));document.querySelectorAll('[data-settings-tab]').forEach(button=>button.classList.toggle('active',button.dataset.settingsTab===name));if(name==='questions')loadClarityQuestions();if(name==='integrations')loadSystemStatus();if(name==='users'&&activeStaffPermissions.includes('users'))loadUsers();}
document.querySelectorAll('[data-settings-tab]').forEach(button=>button.addEventListener('click',()=>showSettingsPanel(button.dataset.settingsTab)));
document.querySelectorAll('[data-settings-jump]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.settingsJump)));

let clarityQuestions=[];
let clarityQuestionsLoaded=false;
const clarityTypeLabels={dialog:'Dialogfrage',scale:'Skala',upload:'Upload-Hinweis',confirmation:'Bestätigung',external:'Technischer Schritt',structured:'Strukturierter Schritt'};
function renderClarityQuestions(){const list=document.querySelector('#clarityQuestionList');if(!list)return;const week=document.querySelector('#clarityQuestionWeek')?.value||'';const query=(document.querySelector('#clarityQuestionSearch')?.value||'').trim().toLowerCase();const filtered=clarityQuestions.filter(item=>(!week||String(item.week)===week)&&(!query||`${item.title} ${item.prompt_text}`.toLowerCase().includes(query)));document.querySelector('#clarityQuestionCount').textContent=`${filtered.length} von ${clarityQuestions.length} Fragen`;list.innerHTML=filtered.length?filtered.map(item=>`<form class="clarity-question-card" data-question-key="${escapeHtml(item.question_key)}"><div class="question-card-head"><div><span>Woche ${Number(item.week)} · Schritt ${Number(item.sort_order)}</span><h4>${escapeHtml(item.title)}</h4></div><i>${escapeHtml(clarityTypeLabels[item.prompt_type]||item.prompt_type)}</i></div><label>Frage oder Arbeitsanweisung<textarea name="promptText" rows="3" minlength="5" maxlength="2000" required>${escapeHtml(item.prompt_text)}</textarea></label><div class="question-card-actions"><small>${item.prompt_text===item.default_prompt_text?'Standardfrage':'Individuell angepasst'}${item.updated_at?` · ${new Date(item.updated_at).toLocaleString('de-DE')}`:''}</small><div><button class="secondary" type="button" data-reset-question>Standard wiederherstellen</button><button class="primary" type="submit">Frage speichern</button></div></div></form>`).join(''):'<div class="empty">Keine Fragen für diesen Filter gefunden.</div>';}
async function loadClarityQuestions(force=false){if(clarityQuestionsLoaded&&!force){renderClarityQuestions();return;}const list=document.querySelector('#clarityQuestionList');if(list)list.innerHTML='<div class="empty">Klarheitsfragen werden geladen …</div>';try{const response=await fetch('/api/clarity?action=settings');const data=await response.json();if(!response.ok)throw new Error(data.error);clarityQuestions=data.questions||[];clarityQuestionsLoaded=true;renderClarityQuestions();}catch(error){if(list)list.innerHTML=`<div class="empty">${escapeHtml(error.message||'Klarheitsfragen konnten nicht geladen werden.')}</div>`;}}
async function updateClarityQuestion(form,action='save'){const questionKey=form.dataset.questionKey;const button=form.querySelector(action==='reset'?'[data-reset-question]':'button[type="submit"]');const promptText=form.elements.promptText.value.trim();button.disabled=true;try{const response=await fetch('/api/clarity?action=settings',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({questionKey,promptText,action})});const data=await response.json();if(!response.ok)throw new Error(data.error);const index=clarityQuestions.findIndex(item=>item.question_key===questionKey);if(index>=0)clarityQuestions[index]={...clarityQuestions[index],...data.question};renderClarityQuestions();toast(action==='reset'?'Standardfrage wurde wiederhergestellt.':'Klarheitsfrage wurde gespeichert.');}catch(error){toast(error.message||'Klarheitsfrage konnte nicht gespeichert werden.');button.disabled=false;}}
document.querySelector('#clarityQuestionWeek')?.addEventListener('change',renderClarityQuestions);
document.querySelector('#clarityQuestionSearch')?.addEventListener('input',renderClarityQuestions);
document.querySelector('#clarityQuestionList')?.addEventListener('submit',event=>{const form=event.target.closest('[data-question-key]');if(!form)return;event.preventDefault();updateClarityQuestion(form);});
document.querySelector('#clarityQuestionList')?.addEventListener('click',event=>{const button=event.target.closest('[data-reset-question]');if(!button)return;const form=button.closest('[data-question-key]');if(confirm('Diese Frage wirklich auf den ausgelieferten Standard zurücksetzen?'))updateClarityQuestion(form,'reset');});

function accessModeLabel(){return 'Automatisch nach Zeitplan';}
function participantMarkup(person, table=false){const info=`<div class="participant"><span class="avatar">${escapeHtml(person.initials)}</span><div><strong>${escapeHtml(person.name)}</strong><small>${escapeHtml(person.email)}</small></div></div>`,phase=customerPhase(person);if(table)return `<div class="table-data participant-control-row" data-participant-id="${escapeHtml(person.id)}">${info}<span class="phase"><b>${escapeHtml(phase)}</b>${escapeHtml(customerStatusLabel(person))}</span><div><div class="progress"><i style="width:${person.progress}%"></i></div><div class="progress-label">${person.progress}% · ${person.completedWeeks.length} von 8 Wochen</div></div><strong>${person.startDate?new Date(`${person.startDate}T00:00:00`).toLocaleDateString('de-DE'):'—'}</strong><span class="gate"><button class="program-open" data-program-id="${escapeHtml(person.id)}">Kundenakte öffnen →</button></span></div>`;return `<div class="participant-row">${info}<span class="phase"><b>${escapeHtml(phase)}</b>${escapeHtml(customerStatusLabel(person))}</span><div><div class="progress"><i style="width:${person.progress}%"></i></div><div class="progress-label">${person.progress}%</div></div><span class="gate"><b>${escapeHtml(person.next)}</b>${escapeHtml(person.programStatus||'aktiv')}</span></div>`;}
function customerPhase(person){return Number(person.processWeek||person.week)>0?`Woche ${Number(person.processWeek||person.week)}`:'Onboarding';}
function customerStatus(person){if(person.progress>=100)return'completed';return person.programStatus==='paused'?'paused':'active';}
function customerStatusLabel(person){return{active:'Aktiv',paused:'Pausiert',completed:'Programm abgeschlossen'}[customerStatus(person)];}
function customerAddress(person){return [person.street,[person.postalCode,person.city].filter(Boolean).join(' '),person.country].filter(Boolean).join(' · ')||'Anschrift noch nicht hinterlegt';}
function customerOverviewMarkup(person){
  const phase=customerPhase(person),start=person.startDate?new Date(`${person.startDate}T00:00:00`).toLocaleDateString('de-DE'):'Noch nicht festgelegt';
  if(participantViewMode==='list')return participantMarkup(person,true);
  if(participantViewMode==='details')return `<article class="customer-detail-card" data-participant-id="${escapeHtml(person.id)}"><div class="customer-detail-profile"><span class="customer-card-avatar">${escapeHtml(person.initials)}</span><div><small>${escapeHtml(person.customerNumber||'Kundennummer wird vergeben')}</small><h2>${escapeHtml(person.name)}</h2><p>${escapeHtml(person.email)}${person.phone?` · ${escapeHtml(person.phone)}`:''}</p></div><button class="program-open" data-program-id="${escapeHtml(person.id)}">Kundenakte öffnen →</button></div><div class="customer-detail-data"><div><small>Status</small><strong>${escapeHtml(phase)}</strong><span>${escapeHtml(person.programStatus||'aktiv')}</span></div><div><small>Programmstart</small><strong>${escapeHtml(start)}</strong><span>${person.progress}% abgeschlossen</span></div><div><small>Name & Adresse</small><strong>${escapeHtml(customerAddress(person))}</strong><span>${escapeHtml(person.birthDate?`Geboren am ${new Date(`${person.birthDate}T00:00:00`).toLocaleDateString('de-DE')}`:'Geburtsdatum nicht hinterlegt')}</span></div></div><div class="customer-card-progress"><i style="width:${person.progress}%"></i></div></article>`;
  return `<article class="customer-tile-card" data-participant-id="${escapeHtml(person.id)}"><div class="customer-tile-top"><span class="customer-card-avatar">${escapeHtml(person.initials)}</span><i>${escapeHtml(phase)}</i></div><small>${escapeHtml(person.customerNumber||'Kundennummer wird vergeben')}</small><h2>${escapeHtml(person.name)}</h2><p>${escapeHtml(person.email)}</p><div class="customer-card-progress"><i style="width:${person.progress}%"></i></div><div class="customer-tile-meta"><span>${person.progress}% Fortschritt</span><span>Start ${escapeHtml(start)}</span></div><button class="program-open" data-program-id="${escapeHtml(person.id)}">Kundenakte öffnen →</button></article>`;
}
function renderParticipants(){const query=normalizeContactSearch(document.querySelector('#participantSearch')?.value||''),week=document.querySelector('#weekFilter')?.value||'',status=document.querySelector('#participantStatusFilter')?.value||'',sort=document.querySelector('#participantSort')?.value||'newest';const filtered=participants.filter(person=>(!query||normalizeContactSearch(collectContactSearchValues(person.searchSource||person).join(' ')).includes(query))&&(!week||String(person.processWeek)===week)&&(!status||customerStatus(person)===status)).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'de'):sort==='process'?a.processWeek-b.processWeek||a.name.localeCompare(b.name,'de'):sort==='progress'?b.progress-a.progress||a.name.localeCompare(b.name,'de'):new Date(b.customerSince||0)-new Date(a.customerSince||0));document.querySelector('#dashboardParticipants').innerHTML=participants.length?participants.slice(0,4).map(person=>participantMarkup(person)).join(''):'<div class="empty">Noch keine Kunden. Ein Interessent erscheint hier automatisch nach vollständig bestätigtem Vertragsabschluss.</div>';const rows=document.querySelector('#participantRows');rows.className=`customer-overview-results ${participantViewMode}`;const listHead=participantViewMode==='list'?'<div class="customer-list-head"><span>Kunde</span><span>Prozessschritt</span><span>Fortschritt</span><span>Startdatum</span><span>Kundenakte</span></div>':'';rows.innerHTML=filtered.length?`${listHead}<div class="customer-result-body">${filtered.map(customerOverviewMarkup).join('')}</div>`:'<div class="empty">Keine Kunden für diese Suche oder Filterauswahl gefunden.</div>';document.querySelector('#participantResultCount').textContent=`${filtered.length} von ${participants.length} ${participants.length===1?'Kunde':'Kunden'}`;document.querySelectorAll('[data-participant-view]').forEach(button=>button.classList.toggle('active',button.dataset.participantView===participantViewMode));rows.querySelectorAll('[data-program-id]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();openCustomerDashboard(button.dataset.programId);}));rows.querySelectorAll('[data-participant-id]').forEach(row=>row.addEventListener('click',()=>openCustomerDashboard(row.dataset.participantId)));}
function setParticipantViewMode(mode){if(!['tiles','list','details'].includes(mode))return;participantViewMode=mode;renderParticipants();}
function setParticipantSection(section,syncNavigation=true){participantSection=section==='logins'?'logins':'overview';const overview=document.querySelector('#participantOverview'),logins=document.querySelector('#participantLoginManager'),dashboard=document.querySelector('#customerDashboard');if(overview)overview.hidden=participantSection!=='overview';if(logins)logins.hidden=participantSection!=='logins';if(dashboard)dashboard.hidden=true;if(syncNavigation&&document.querySelector('[data-panel="participants"]')?.classList.contains('active'))renderContextNavigation('participants');}
function resetCustomerListView(){activeCustomerDashboard=null;customerDashboardPage='dashboard';setParticipantSection('overview',false);}
const customerConversationLabels=['Sind Name, E-Mail-Adresse und Telefonnummer korrekt?','Wie sieht die berufliche Situation momentan aus?','Was möchte der Kunde durch das Coaching konkret erreichen?','Was hindert den Kunden momentan am stärksten daran?','Was wurde bisher versucht und warum hat es noch nicht funktioniert?','Wie verbindlich ist die Bereitschaft für die nächsten Schritte?'];
function customerProcessWeek(program){const configured=Number(program?.access?.processWeek);if(Number.isInteger(configured)&&configured>=1&&configured<=8)return configured;const completed=new Set((program?.access?.completedWeeks||[]).map(Number));return Array.from({length:8},(_,index)=>index+1).find(week=>!completed.has(week))||8;}
function customerWeekMarkup(program){const states=program?.access?.weekStates||[],processWeek=customerProcessWeek(program);return Array.from({length:8},(_,index)=>{const week=index+1,state=states.find(item=>Number(item.week)===week)||{},definition=gateData.find(item=>Number(item.week)===week),current=processWeek===week;return`<article class="customer-week-item ${state.completed?'completed':current?'current':state.accessible?'available':'scheduled'}"><span>${state.completed?'✓':week}</span><small>Woche ${week}</small><strong>${escapeHtml(definition?.title||`Woche ${week}`)}</strong><i>${state.completed?'Abgeschlossen':current?'Aktueller Prozessschritt':state.accessible?'Verfügbar':'Geplant'}</i></article>`;}).join('');}
function customerContactMarkup(profile){const address=[profile.street,[profile.postal_code,profile.city].filter(Boolean).join(' '),profile.country].filter(Boolean).map(escapeHtml).join('<br>')||'Noch nicht hinterlegt',mobile=profile.mobile_phone||'',whatsapp=profile.whatsapp_phone||(profile.whatsapp_same_as_mobile?mobile:'');return`<dl class="customer-contact-data"><div><dt>Name</dt><dd>${escapeHtml(profile.name)}</dd></div><div><dt>Geburtsdatum</dt><dd>${profile.birth_date?new Date(`${profile.birth_date}T00:00:00`).toLocaleDateString('de-DE'):'Nicht hinterlegt'}</dd></div><div class="wide"><dt>Anschrift</dt><dd>${address}</dd></div><div><dt>E-Mail</dt><dd>${escapeHtml(profile.email)}</dd></div><div><dt>Telefon</dt><dd>${escapeHtml(profile.phone||'Nicht hinterlegt')}</dd></div><div><dt>Mobilnummer</dt><dd>${escapeHtml(mobile||'Nicht hinterlegt')}</dd></div><div><dt>WhatsApp</dt><dd>${escapeHtml(whatsapp||'Nicht hinterlegt')}<small>${profile.whatsapp_same_as_mobile?'Identisch mit Mobilnummer':'Eigene WhatsApp-Nummer'}</small></dd></div></dl>`;}
function renderCustomerConversation(data){const lead=data.leadDashboard?.lead,form=document.querySelector('#customerConversationForm'),container=document.querySelector('#customerConversationQuestions');if(!lead){container.innerHTML='<div class="empty">Zu diesem Kunden wurde keine frühere Interessentenakte gefunden.</div>';form.querySelector('[type="submit"]').disabled=true;return;}form.querySelector('[type="submit"]').disabled=false;const answers=lead.qualification_answers||{};container.innerHTML=customerConversationLabels.map((label,index)=>`<label><b>${index+1}. ${escapeHtml(label)}</b><textarea name="q${index+1}" rows="3">${escapeHtml(answers[`q${index+1}`]||'')}</textarea></label>`).join('');form.elements.internalNotes.value=lead.internal_notes||'';const completed=['consultation','offer','customer'].includes(lead.status);document.querySelector('#customerConversationState').textContent=completed?'Gespräch dokumentiert':'Dokumentation offen';document.querySelector('#customerConversationAppointment').innerHTML=lead.appointment_start?`<strong>Termin: ${crmDate(lead.appointment_start)}</strong>${lead.meet_url?`<a href="${escapeHtml(lead.meet_url)}" target="_blank" rel="noopener">Google Meet öffnen ↗</a>`:''}`:'<span>Noch kein Gesprächstermin hinterlegt</span>';}
function customerDocumentMarkup(document,person){const size=document.byte_size?`${Math.max(1,Math.round(Number(document.byte_size)/1024))} KB`:'',source=document.source==='staff'?'Vom Team bereitgestellt':document.source==='system'?'Vom System erstellt':'Vom Kunden hochgeladen';return`<article><span>▤</span><div><strong>${escapeHtml(document.display_title||document.original_file_name)}</strong><small>${escapeHtml([source,`Woche ${document.week||0}`,size,crmDate(document.created_at)].filter(Boolean).join(' · '))}</small><i>${escapeHtml(document.original_file_name)}</i></div><a href="/api/customer-records?action=document-download&amp;participantId=${encodeURIComponent(person.id)}&amp;documentId=${encodeURIComponent(document.id)}" target="_blank" rel="noopener">Öffnen ↗</a></article>`;}
function renderCustomerDocuments(data){const {customer,person}=data,contracts=customer?.contracts||[],documents=customer?.documents||[];document.querySelector('#customerContractState').textContent=`${contracts.length} ${contracts.length===1?'Vertrag':'Verträge'}`;document.querySelector('#customerOfficialDocuments').innerHTML=contracts.length?contracts.flatMap(contract=>[{title:contract.title||'Vertragsdokument',ready:Boolean(contract.document_confirmed_at),type:'Vertrag',date:contract.document_confirmed_at||contract.created_at},{title:`Videovertrag · ${contract.title||'Vertragsabschluss'}`,ready:Boolean(contract.video_contract_confirmed_at),type:'Videovertrag',date:contract.video_contract_confirmed_at||contract.created_at}]).map(item=>`<article class="${item.ready?'ready':'pending'}"><span>${item.ready?'✓':'○'}</span><div><small>${escapeHtml(item.type)}</small><strong>${escapeHtml(item.title)}</strong><p>${item.ready?`Bestätigt am ${crmDate(item.date)}`:'Noch nicht vollständig bestätigt'}</p></div></article>`).join(''):'<div class="empty">Noch keine Vertragsunterlagen vorhanden.</div>';document.querySelector('#customerDocumentCount').textContent=`${documents.length} ${documents.length===1?'Dokument':'Dokumente'}`;document.querySelector('#customerDocumentInbox').innerHTML=documents.length?documents.map(document=>customerDocumentMarkup(document,person)).join(''):'<div class="empty">Noch keine Uploads oder freigegebenen Unterlagen vorhanden.</div>';}
function renderCustomerFinance(data){const customer=data.customer||{},finance=customer.finance||data.leadDashboard?.finance||{contractTotal:0,paidTotal:0,openBalance:0},bank=customer.bankAccount,payments=customer.payments||[],contracts=customer.contracts||[];document.querySelector('#customerAccountState').textContent=finance.openBalance>0?'Saldo offen':'Ausgeglichen';document.querySelector('#customerAccountPage').innerHTML=`<section class="customer-finance-cards"><article><small>Vertragsvolumen</small><strong>${euro(finance.contractTotal)}</strong></article><article><small>Zahlungseingänge</small><strong>${euro(finance.paidTotal)}</strong></article><article class="${finance.openBalance>0?'open':'paid'}"><small>Offener Saldo</small><strong>${euro(finance.openBalance)}</strong></article></section><section class="customer-bank-data"><h3>Bankverbindung</h3>${bank?`<dl><div><dt>Kontoinhaber</dt><dd>${escapeHtml(bank.account_holder||'—')}</dd></div><div><dt>IBAN</dt><dd>${escapeHtml(bank.iban||'—')}</dd></div><div><dt>BIC</dt><dd>${escapeHtml(bank.bic||'—')}</dd></div><div><dt>Referenz</dt><dd>${escapeHtml(bank.payment_reference||'—')}</dd></div></dl>`:'<div class="empty">Noch keine Bankverbindung hinterlegt.</div>'}</section>`;document.querySelector('#customerBillingState').textContent=`${contracts.length} Verträge · ${payments.length} Zahlungen`;const entries=[...contracts.map(item=>({date:item.signed_at||item.created_at,title:item.title||'Vertrag',copy:`${contractStatusLabels[item.status]||item.status} · ${euro(item.amount)}`,tone:'contract'})),...payments.map(item=>({date:item.booked_at||item.created_at,title:'Zahlungseingang',copy:`${euro(item.amount)} · ${item.reference||'ohne Referenz'}`,tone:'payment'}))].sort((a,b)=>new Date(b.date)-new Date(a.date));document.querySelector('#customerBillingPage').innerHTML=entries.length?entries.map(item=>`<article class="${item.tone}"><span>${item.tone==='payment'?'€':'▤'}</span><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.copy)}</p></div><time>${crmDate(item.date)}</time></article>`).join(''):'<div class="empty">Noch keine Rechnungs- oder Zahlungsdaten vorhanden.</div>';}
function renderCustomerMessages(data){const communications=data.customer?.communications||data.leadDashboard?.communications||[],visible=communications.filter(item=>item.channel!=='whatsapp'||item.direction==='outbound');document.querySelector('#customerMessageCount').textContent=`${visible.length} ${visible.length===1?'Nachricht':'Nachrichten'}`;document.querySelector('#customerMessagePage').innerHTML=visible.length?visible.map(item=>`<article><span class="${escapeHtml(item.direction)}">${item.channel==='whatsapp'?'WA':'@'}</span><div><strong>${escapeHtml(item.subject||'Nachricht')}</strong><p>${escapeHtml(item.body||item.preview||'Kein Nachrichtentext')}</p><small>${item.direction==='inbound'?'Eingang':'Ausgang'} · ${crmDate(item.occurred_at)}</small></div></article>`).join(''):'<div class="empty">Noch keine Kundenkommunikation vorhanden.</div>';const whatsapp=communications.filter(item=>item.channel==='whatsapp'),profile=data.customer?.profile||data.program.profile;document.querySelector('#customerWhatsappState').textContent=data.customer?.integrations?.whatsapp?.configured?'WhatsApp verbunden':'WhatsApp noch nicht verbunden';document.querySelector('#customerWhatsappState').classList.toggle('active',Boolean(data.customer?.integrations?.whatsapp?.configured));document.querySelector('#customerWhatsappName').textContent=profile.name;document.querySelector('#customerWhatsappNumber').textContent=profile.whatsapp_phone||(profile.whatsapp_same_as_mobile?profile.mobile_phone:'')||'Keine WhatsApp-Nummer';document.querySelector('#customerWhatsappAvatar').textContent=data.person.initials;document.querySelector('#customerWhatsappMessages').innerHTML=whatsapp.length?whatsapp.slice().reverse().map(item=>`<article class="${escapeHtml(item.direction)}"><p>${escapeHtml(item.body||item.preview||'')}</p><small>${crmDate(item.occurred_at)} · ${item.direction==='outbound'?'Ausgang':'Eingang'}</small></article>`).join(''):'<div class="customer-phone-empty">Noch keine WhatsApp-Nachrichten.</div>';const phoneMessages=document.querySelector('#customerWhatsappMessages');phoneMessages.scrollTop=phoneMessages.scrollHeight;document.querySelector('#customerWhatsappForm').querySelector('[type="submit"]').disabled=!data.customer?.integrations?.whatsapp?.configured;}
function renderCustomerAppointments(data){const appointments=data.customer?.appointments||[],now=Date.now(),upcoming=appointments.filter(item=>item.status==='scheduled'&&new Date(item.starts_at).getTime()>=now),past=appointments.filter(item=>!upcoming.includes(item));document.querySelector('#customerAppointmentState').textContent=upcoming.length?`${upcoming.length} bevorstehend`:'Kein Termin geplant';const group=(title,items)=>`<section><h3>${title}</h3>${items.length?items.map(item=>`<article><time><b>${new Date(item.starts_at).toLocaleDateString('de-DE',{day:'2-digit',month:'short'})}</b><span>${new Date(item.starts_at).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})} Uhr</span></time><div><strong>${escapeHtml(item.title||'Kundentermin')}</strong><p>${escapeHtml(item.source==='google_calendar'?'Google Kalender':'CRM-Termin')} · ${escapeHtml(item.status==='cancelled'?'Abgesagt':item.status==='completed'?'Abgeschlossen':'Geplant')}</p></div><nav>${item.meet_url?`<a href="${escapeHtml(item.meet_url)}" target="_blank" rel="noopener">Meet öffnen ↗</a>`:''}${item.google_event_url?`<a href="${escapeHtml(item.google_event_url)}" target="_blank" rel="noopener">Kalender ↗</a>`:''}</nav></article>`).join(''):'<div class="empty">Keine Termine in diesem Bereich.</div>'}</section>`;document.querySelector('#customerAppointmentPage').innerHTML=group('Nächste Termine',upcoming)+group('Vergangene Termine',past.slice().reverse());}
function renderCustomerDashboard(data){const {person,program,leadDashboard,customer}=data,profile=customer?.profile||program.profile,progress=person.progress||0,photo=profile.photoUrl||'',processWeek=customerProcessWeek(program),processDefinition=gateData.find(item=>Number(item.week)===processWeek);document.querySelector('#customerDashboardInitials').innerHTML=photo?`<img src="${escapeHtml(photo)}" alt="Profilbild von ${escapeHtml(profile.name)}">`:escapeHtml(person.initials);document.querySelector('#customerDashboardName').textContent=profile.name;document.querySelector('#customerDashboardPhase').textContent=`Woche ${processWeek} · ${processDefinition?.title||'Aktueller Prozessschritt'}`;document.querySelector('#customerDashboardContact').textContent=[profile.customer_number||person.customerNumber,profile.birth_date?`geb. ${new Date(`${profile.birth_date}T00:00:00`).toLocaleDateString('de-DE')}`:'Geburtsdatum offen',profile.email].filter(Boolean).join(' · ');document.querySelector('#customerProgramHeadline').textContent=`Woche ${processWeek} von 8 · ${processDefinition?.title||profile.name}`;document.querySelector('#customerProgramProgress').textContent=`${progress} % abgeschlossen`;const weeks=customerWeekMarkup(program);document.querySelector('#customerWeekTrack').innerHTML=weeks;document.querySelector('#customerProgramPageWeeks').innerHTML=weeks;document.querySelector('#customerSummaryContact').innerHTML=customerContactMarkup(profile);document.querySelector('#customerDataPage').innerHTML=customerContactMarkup(profile);const finance=customer?.finance||leadDashboard?.finance||{openBalance:0};document.querySelector('#customerOpenBalance').textContent=euro(finance.openBalance);document.querySelector('#customerBalanceState').textContent=finance.openBalance>0?'Zahlung oder Restbetrag noch offen':'Keine offenen Forderungen';const customerCommunications=customer?.communications||leadDashboard?.communications||[],communicationCount=customerCommunications.filter(item=>item.channel!=='whatsapp'||item.direction==='outbound').length,openTasks=(leadDashboard?.tasks||[]).filter(item=>!item.completed).length,openQuestions=(leadDashboard?.questions||[]).filter(item=>item.status==='open').length;document.querySelector('#customerCommunicationSummary').innerHTML=`<strong>${communicationCount}</strong><span>${communicationCount===1?'Nachricht dokumentiert':'Nachrichten dokumentiert'}</span>`;document.querySelector('#customerTaskSummary').innerHTML=`<strong>${openTasks+openQuestions}</strong><span>${openTasks} Aufgaben · ${openQuestions} Kundenfragen offen</span>`;document.querySelector('#customerLoginPage').innerHTML=`<dl class="customer-contact-data"><div><dt>Kundennummer</dt><dd>${escapeHtml(person.customerNumber||'Wird vergeben')}</dd></div><div><dt>Portal-Login</dt><dd>${escapeHtml(person.loginName||'Wird automatisch erzeugt')}</dd></div><div><dt>Zugangsstatus</dt><dd>${escapeHtml(participantLoginStatus(person)[0])}</dd></div><div><dt>E-Mail</dt><dd>${escapeHtml(person.email)}</dd></div></dl>`;renderCustomerConversation(data);renderCustomerDocuments(data);renderCustomerFinance(data);renderCustomerMessages(data);renderCustomerAppointments(data);setCustomerDashboardPage(customerDashboardPage,false);renderContextNavigation('participants');}
function setCustomerDashboardPage(page,syncNavigation=true){const allowed=['dashboard','data','conversation','program','login','documents','documentInbox','account','billing','messages','whatsapp','appointments'];if(!allowed.includes(page)||!canAccessCustomerPage(page))page='dashboard';customerDashboardPage=page;document.querySelector('#openCustomerProgram').hidden=!activeStaffPermissions.includes('program');document.querySelector('#openCustomerLogin').hidden=!activeStaffPermissions.includes('customers');document.querySelectorAll('[data-customer-summary-permission]').forEach(card=>{card.hidden=!activeStaffPermissions.includes(card.dataset.customerSummaryPermission);});document.querySelectorAll('[data-customer-page]').forEach(section=>{const active=section.dataset.customerPage===page;section.hidden=!active;section.classList.toggle('active',active);});if(syncNavigation&&activeCustomerDashboard)renderContextNavigation('participants');window.scrollTo({top:0,behavior:'smooth'});}
async function openCustomerDashboard(participantId,page='dashboard'){const person=participants.find(item=>item.id===participantId);if(!person)return toast('Kunde wurde nicht gefunden.');participantSection='overview';customerDashboardPage=page;document.querySelector('#participantOverview').hidden=true;document.querySelector('#participantLoginManager').hidden=true;document.querySelector('#customerDashboard').hidden=false;document.querySelector('#customerDashboardName').textContent='Kundenakte wird geladen …';activeCustomerDashboard={person,program:null,leadDashboard:null,customer:null};renderContextNavigation('participants');try{const linkedLeadId=person.linkedLeadId||leads.find(item=>item.converted_user_profile_id===participantId)?.id;const [programResponse,leadResponse,customerResponse]=await Promise.all([fetch(`/api/program-control?participantId=${encodeURIComponent(participantId)}`),linkedLeadId?fetch(`/api/leads?action=dashboard&id=${encodeURIComponent(linkedLeadId)}`):Promise.resolve(null),fetch(`/api/customer-records?action=overview&participantId=${encodeURIComponent(participantId)}`)]);const program=await programResponse.json(),customer=await customerResponse.json();if(!programResponse.ok)throw new Error(program.error);if(!customerResponse.ok)throw new Error(customer.error);let leadDashboard=null;if(leadResponse){leadDashboard=await leadResponse.json();if(!leadResponse.ok)throw new Error(leadDashboard.error);}activeCustomerDashboard={person,program,leadDashboard,customer};renderCustomerDashboard(activeCustomerDashboard);}catch(error){resetCustomerListView();renderContextNavigation('participants');toast(error.message||'Kunden-Dashboard konnte nicht geladen werden.');}}
function closeCustomerDashboard(){resetCustomerListView();renderParticipants();renderContextNavigation('participants');window.scrollTo({top:0,behavior:'smooth'});}

function dashboardNumber(value,digits=0){return Number(value||0).toLocaleString('de-DE',{minimumFractionDigits:digits,maximumFractionDigits:digits});}
function renderDashboardClarity(clarity={}){const phases=clarity.phases||[],positions=[6,50,94],labels={start:'Start',midpoint:'Halbzeit',end:'Ende'};const points=phases.map((item,index)=>item.average===null||item.average===undefined?null:{...item,x:positions[index],y:10+Number(item.average)*8}).filter(Boolean);document.querySelector('#dashboardClarityLine').setAttribute('points',points.map(item=>`${item.x},${100-item.y}`).join(' '));document.querySelector('#dashboardClarityPoints').innerHTML=points.map(item=>`<span style="left:${item.x}%;bottom:${item.y}%">${dashboardNumber(item.average,1)}<small>${escapeHtml(labels[item.phase]||item.phase)} · ${item.count}</small></span>`).join('');document.querySelector('#dashboardClarityEmpty').hidden=points.length>0;const hasGain=clarity.averageGain!==null&&clarity.averageGain!==undefined;document.querySelector('#dashboardClarityGain').textContent=hasGain?`${Number(clarity.averageGain)>=0?'+':''}${dashboardNumber(clarity.averageGain,1)}`:'—';document.querySelector('#dashboardClarityCopy').textContent=clarity.completedComparisons?`${clarity.completedComparisons} vollständige Start-/Endmessung${clarity.completedComparisons===1?'':'en'} · Skala 1–10`:'Noch keine vollständige Start-/Endmessung';}
function renderDashboardDistribution(values=[],onboarding=0){const counts=Array.from({length:8},(_,index)=>Number(values[index]||0)),maximum=Math.max(1,...counts);document.querySelector('#dashboardWeekCounts').innerHTML=counts.map(value=>`<i style="height:${Math.max(25,25+value/maximum*70)}px">${value}</i>`).join('');document.querySelector('#dashboardWeekLabels').innerHTML=counts.map((value,index)=>`<span class="${value===maximum&&value>0?'current':''}">${index+1}</span>`).join('');document.querySelector('#dashboardOnboardingCount').textContent=`${Number(onboarding||0)} ${Number(onboarding)===1?'Kunde':'Kunden'} im Onboarding`;document.querySelectorAll('.metrics article.dark .bars i').forEach((bar,index)=>{bar.style.height=`${Math.max(12,counts[index]/maximum*100)}%`;});}
function openDashboardAction(item){if(!item?.entityId)return;if(item.entityType==='participant'){showView('participants');openCustomerDashboard(item.entityId);}else if(item.entityType==='lead'){showView('leads');openLeadDashboard(item.entityId);}}
function renderDashboardAttention(attention={}){const list=document.querySelector('#dashboardAttentionList'),items=attention.items||[];document.querySelector('#dashboardAttentionCount').textContent=String(attention.total||0);list.innerHTML=items.length?items.map(item=>`<article data-dashboard-action="${escapeHtml(item.id)}"><i class="${escapeHtml(item.tone||'orange')}">${escapeHtml(item.icon||'!')}</i><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.subtitle)}</p></div><button type="button">${escapeHtml(item.actionLabel||'Öffnen')}</button></article>`).join(''):'<div class="empty">Aktuell gibt es keine offenen Vorgänge. Alles im grünen Bereich.</div>';list.querySelectorAll('[data-dashboard-action]').forEach(element=>element.addEventListener('click',()=>openDashboardAction(items.find(item=>item.id===element.dataset.dashboardAction))));}
function renderCommandDashboard(data){const generated=new Date(data.generatedAt||Date.now()),hour=generated.getHours(),firstName=(data.adminName||'Markus').trim().split(/\s+/)[0];document.querySelector('#dashboardDate').textContent=new Intl.DateTimeFormat('de-DE',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(generated);document.querySelector('#dashboardGreeting').textContent=`${hour<11?'Guten Morgen':hour<18?'Guten Tag':'Guten Abend'}, ${firstName}.`;const summary=data.summary||{};document.querySelector('#dashboardLiveSummary').textContent=`${summary.activeLeads||0} Interessenten · ${summary.unreadMessages||0} ungelesene Nachrichten`;document.querySelector('#activeCustomerCount').textContent=String(summary.activeCustomers||0);document.querySelector('#dashboardNewCustomers').textContent=`+${summary.newCustomers||0} diesen Monat`;document.querySelector('#dashboardOpenGates').textContent=String(summary.openGates||0);document.querySelector('#dashboardOpenGateCopy').textContent=summary.openGates?`${summary.overdueGates||0} davon ohne Aktivität seit über 48 Stunden`:'Keine offenen Pflichtschritte';renderDashboardClarity(data.clarity);renderDashboardDistribution(data.weekDistribution,summary.onboarding);renderDashboardAttention(data.attention);}
async function loadCommandDashboard(){try{const response=await fetch('/api/leads?action=command-dashboard'),data=await response.json();if(!response.ok)throw new Error(data.error);renderCommandDashboard(data);}catch(error){document.querySelector('#dashboardLiveSummary').textContent='Live-Daten konnten nicht geladen werden';document.querySelector('#dashboardAttentionList').innerHTML=`<div class="empty system-error">${escapeHtml(error.message||'Dashboard konnte nicht geladen werden.')}</div>`;}}
function participantLoginStatus(person){if(person.mustChangePassword)return['Einmalpasswort aktiv','change'];if(person.passwordChangedAt)return['Persönliches Passwort','active'];return['Einrichtung offen','pending'];}
function renderParticipantLogins(){const rows=document.querySelector('#participantLoginRows');if(!rows)return;document.querySelector('#participantLoginCount').textContent=`${participants.length} ${participants.length===1?'Zugang':'Zugänge'}`;rows.innerHTML=participants.length?participants.map(person=>{const [label,tone]=participantLoginStatus(person);return `<div class="participant-login-row"><div class="participant"><span class="avatar">${escapeHtml(person.initials)}</span><div><strong>${escapeHtml(person.name)}</strong><small>${escapeHtml(person.email)}</small></div></div><strong>${escapeHtml(person.customerNumber||'Wird vergeben')}</strong><code>${escapeHtml(person.loginName||'Wird automatisch erzeugt')}</code><span class="login-state ${tone}">${escapeHtml(label)}</span><button type="button" class="user-manage" data-manage-participant-login="${escapeHtml(person.id)}">Verwalten →</button></div>`;}).join(''):'<div class="empty">Noch keine Teilnehmer-Zugänge vorhanden.</div>';rows.querySelectorAll('[data-manage-participant-login]').forEach(button=>button.addEventListener('click',()=>openParticipantLogin(button.dataset.manageParticipantLogin)));}
document.querySelector('#participantSearch').addEventListener('input',renderParticipants);document.querySelector('#weekFilter').addEventListener('change',renderParticipants);document.querySelector('#participantStatusFilter').addEventListener('change',renderParticipants);document.querySelector('#participantSort').addEventListener('change',renderParticipants);document.querySelectorAll('[data-participant-view]').forEach(button=>button.addEventListener('click',()=>setParticipantViewMode(button.dataset.participantView)));
document.querySelector('#closeCustomerDashboard').addEventListener('click',closeCustomerDashboard);
document.querySelector('#openCustomerProgram').addEventListener('click',()=>openProgramControl(activeCustomerDashboard?.person?.id));
document.querySelector('#editCustomerProgram').addEventListener('click',()=>openProgramControl(activeCustomerDashboard?.person?.id));
document.querySelector('#editCustomerData').addEventListener('click',()=>openProgramControl(activeCustomerDashboard?.person?.id));
document.querySelector('#openCustomerLogin').addEventListener('click',()=>setCustomerDashboardPage('login'));
document.querySelector('#manageCustomerLogin').addEventListener('click',()=>openParticipantLogin(activeCustomerDashboard?.person?.id));
function adminFileAsBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||'').split(',')[1]||'');reader.onerror=()=>reject(new Error('Die Datei konnte nicht gelesen werden.'));reader.readAsDataURL(file);});}
async function refreshOpenCustomer(){const id=activeCustomerDashboard?.person?.id,page=customerDashboardPage;if(id)await openCustomerDashboard(id,page);}
document.querySelector('#customerDocumentUploadForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,file=form.elements.file.files?.[0],button=form.querySelector('[type="submit"]');if(!file)return toast('Bitte eine Datei auswählen.');button.disabled=true;try{const response=await fetch('/api/customer-records?action=document-upload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({participantId:activeCustomerDashboard?.person?.id,title:form.elements.title.value,documentType:form.elements.documentType.value,visibility:form.elements.customerVisible.checked?'customer':'staff',fileName:file.name,mimeType:file.type,contentBase64:await adminFileAsBase64(file)})}),data=await response.json();if(!response.ok)throw new Error(data.error);form.reset();form.elements.customerVisible.checked=true;await refreshOpenCustomer();toast('Dokument wurde sicher in der Kundenakte gespeichert.');}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.querySelector('#customerAvatarInput').addEventListener('change',async event=>{const file=event.currentTarget.files?.[0];if(!file)return;try{const response=await fetch('/api/customer-records?action=avatar-upload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({participantId:activeCustomerDashboard?.person?.id,fileName:file.name,mimeType:file.type,contentBase64:await adminFileAsBase64(file)})}),data=await response.json();if(!response.ok)throw new Error(data.error);await refreshOpenCustomer();toast('Kundenfoto wurde gespeichert.');}catch(error){toast(error.message);}finally{event.currentTarget.value='';}});
document.querySelector('#customerWhatsappForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,message=form.elements.message.value.trim(),button=form.querySelector('[type="submit"]');if(!message)return;button.disabled=true;try{const response=await fetch('/api/customer-records?action=whatsapp-send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({participantId:activeCustomerDashboard?.person?.id,message})}),data=await response.json();if(!response.ok)throw new Error(data.error);form.reset();await refreshOpenCustomer();toast('WhatsApp-Nachricht wurde versendet und protokolliert.');}catch(error){toast(error.message);}finally{button.disabled=!activeCustomerDashboard?.customer?.integrations?.whatsapp?.configured;}});
document.querySelector('#customerWhatsappSame').addEventListener('change',event=>{const whatsapp=document.querySelector('#customerWhatsappPhone');whatsapp.disabled=event.currentTarget.checked;if(event.currentTarget.checked)whatsapp.value=document.querySelector('#customerMobilePhone').value;});
document.querySelector('#customerMobilePhone').addEventListener('input',event=>{if(document.querySelector('#customerWhatsappSame').checked)document.querySelector('#customerWhatsappPhone').value=event.currentTarget.value;});
document.querySelector('#customerConversationForm').addEventListener('submit',async event=>{event.preventDefault();const lead=activeCustomerDashboard?.leadDashboard?.lead;if(!lead)return toast('Für diesen Kunden fehlt die verknüpfte Interessentenakte.');const button=event.currentTarget.querySelector('[type="submit"]');button.disabled=true;const[firstName,lastName]=splitLeadName(lead);const qualificationAnswers=Object.fromEntries(Array.from({length:6},(_,index)=>[`q${index+1}`,event.currentTarget.elements[`q${index+1}`]?.value||'']));try{const response=await fetch('/api/leads?action=update',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:lead.id,firstName:lead.first_name||firstName,lastName:lead.last_name||lastName,email:lead.email,phone:lead.phone||'',status:'customer',challenge:lead.challenge||'',internalNotes:event.currentTarget.elements.internalNotes.value,qualificationAnswers})}),data=await response.json();if(!response.ok)throw new Error(data.error);activeCustomerDashboard.leadDashboard.lead=data.lead;updateLeadCache(data.lead);renderCustomerConversation(activeCustomerDashboard);toast('Kundengespräch wurde gespeichert.');}catch(error){toast(error.message);}finally{button.disabled=false;}});
let gateSettingsLoaded=false;
function renderGateGrid(){const grid=document.querySelector('#gateGrid');grid.innerHTML=gateData.map((gate,index)=>`<article class="gate-card ${index<3?'complete':index===3?'current':''}" data-gate-week="${gate.week}"><div class="gate-top"><span>${Number(gate.week)===0?'Start':`Woche ${Number(gate.week)}`}</span><div class="gate-card-tools"><i>${index<3?'Abgeschlossen':index===3?'Aktiv':'Gesperrt'}</i><button type="button" class="gate-menu" data-edit-gate="${gate.week}" aria-label="${escapeHtml(gate.title)} bearbeiten" title="Gate bearbeiten">•••</button></div></div><h2>${escapeHtml(gate.title)}</h2><p>${escapeHtml(gate.description)}</p><ul>${gate.items.map(item=>`<li><button type="button" data-edit-gate="${gate.week}" data-gate-key="${escapeHtml(item.gateKey)}"><span>${escapeHtml(item.label)}</span><small>Bearbeiten</small></button></li>`).join('')}</ul></article>`).join('');}
async function loadGateSettings(force=false){if(gateSettingsLoaded&&!force)return renderGateGrid();try{const response=await fetch('/api/gates?action=settings'),data=await response.json();if(!response.ok)throw new Error(data.error);gateData=data.weeks||gateData;gateSettingsLoaded=true;renderGateGrid();}catch(error){toast(error.message||'Wochen-Gates konnten nicht geladen werden.');renderGateGrid();}}
const gateSettingsDialog=document.querySelector('#gateSettingsDialog'),gateSettingsForm=document.querySelector('#gateSettingsForm');
function openGateSettings(week,fieldKey=''){const gate=gateData.find(item=>Number(item.week)===Number(week));if(!gate)return;gateSettingsForm.elements.week.value=String(gate.week);gateSettingsForm.elements.title.value=gate.title;gateSettingsForm.elements.description.value=gate.description;document.querySelector('#gateDialogWeek').textContent=Number(gate.week)===0?'Start · Onboarding':`Woche ${Number(gate.week)}`;document.querySelector('#gateFieldEditors').innerHTML=gate.items.map((item,index)=>`<div class="gate-field-editor"><span>${String(index+1).padStart(2,'0')}</span><label>Pflichtfeld ${index+1}<input name="gateLabel" data-gate-field-key="${escapeHtml(item.gateKey)}" value="${escapeHtml(item.label)}" minlength="2" maxlength="240" required><small>Die technische Gate-ID bleibt geschützt.</small></label></div>`).join('');gateSettingsDialog.showModal();const target=fieldKey?gateSettingsForm.querySelector(`[data-gate-field-key="${fieldKey}"]`):gateSettingsForm.elements.title;requestAnimationFrame(()=>target?.focus());}
async function saveGateSettings(action='save'){const button=gateSettingsForm.querySelector(action==='reset'?'[data-reset-gate]':'button[type="submit"]');button.disabled=true;try{const items=[...gateSettingsForm.querySelectorAll('[data-gate-field-key]')].map(input=>({gateKey:input.dataset.gateFieldKey,label:input.value.trim()}));const response=await fetch('/api/gates?action=settings',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({week:Number(gateSettingsForm.elements.week.value),title:gateSettingsForm.elements.title.value.trim(),description:gateSettingsForm.elements.description.value.trim(),items,action})}),data=await response.json();if(!response.ok)throw new Error(data.error);gateData=data.weeks||gateData;gateSettingsLoaded=true;renderGateGrid();gateSettingsDialog.close();toast(action==='reset'?'Gate-Standard wurde wiederhergestellt.':'Wochen-Gate wurde gespeichert.');}catch(error){toast(error.message||'Wochen-Gate konnte nicht gespeichert werden.');}finally{button.disabled=false;}}
renderGateGrid();
document.querySelector('#gateGrid').addEventListener('click',event=>{const button=event.target.closest('[data-edit-gate]');if(button)openGateSettings(button.dataset.editGate,button.dataset.gateKey||'');});
document.querySelectorAll('[data-close-gate-settings]').forEach(button=>button.addEventListener('click',()=>gateSettingsDialog.close()));
gateSettingsForm.addEventListener('submit',event=>{event.preventDefault();saveGateSettings();});
gateSettingsForm.querySelector('[data-reset-gate]').addEventListener('click',()=>{if(confirm('Dieses Wochen-Gate wirklich auf den ausgelieferten Standard zurücksetzen?'))saveGateSettings('reset');});

const selectedPermissions=form=>[...form.querySelectorAll('[name="permissions"]:checked')].map(input=>input.value);
const userDialog=document.querySelector('#userDialog');document.querySelector('#openUser').addEventListener('click',()=>userDialog.showModal());document.querySelectorAll('[data-close-user]').forEach(b=>b.addEventListener('click',()=>userDialog.close()));document.querySelector('#userForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const values=Object.fromEntries(new FormData(form));values.permissions=selectedPermissions(form);const response=await fetch('/api/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});const data=await response.json();if(!response.ok)return toast(data.error);userDialog.close();form.reset();toast(data.passwordResetSent?'Benutzer angelegt. Passwort-E-Mail wurde versendet.':'Benutzer mit Startpasswort wurde angelegt.');loadUsers();});
const userEditDialog=document.querySelector('#userEditDialog');const userEditForm=document.querySelector('#userEditForm');document.querySelectorAll('[data-close-user-edit]').forEach(button=>button.addEventListener('click',()=>userEditDialog.close()));
function openUserEdit(id){const user=users.find(item=>item.id===id);if(!user)return;const participant=Boolean(user.participant_progress?.length);userEditForm.elements.id.value=user.id;userEditForm.elements.role.value=user.role;userEditForm.elements.status.value=user.status;userEditForm.elements.staffRole.value=user.staff_role||'';document.querySelector('#editUserName').textContent=user.name;document.querySelector('#editUserEmail').textContent=user.email;userEditForm.querySelectorAll('[name="permissions"]').forEach(input=>{input.checked=(user.permissions||[]).includes(input.value);if(input.value==='clara_program'){input.disabled=!participant;input.closest('label').title=participant?'Teilnehmerzugang aus einem bestätigten Vertrag':'Wird erst nach bestätigtem Lead-Vertragsabschluss freigeschaltet';}});userEditDialog.showModal();}
userEditForm.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const payload={id:form.elements.id.value,role:form.elements.role.value,staffRole:form.elements.role.value==='admin'?form.elements.staffRole.value:'',status:form.elements.status.value,permissions:selectedPermissions(form)};const response=await fetch('/api/users',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)return toast(data.error);userEditDialog.close();toast('Rolle und Benutzerrechte wurden gespeichert.');loadUsers();});
document.querySelector('#resetUserPassword').addEventListener('click',async()=>{const response=await fetch('/api/users',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:userEditForm.elements.id.value,action:'password_reset'})});const data=await response.json();toast(response.ok?'Passwort-Reset wurde per E-Mail versendet.':data.error);});

const programDialog=document.querySelector('#programDialog');
document.querySelectorAll('[data-close-program]').forEach(button=>button.addEventListener('click',()=>programDialog.close()));
function renderProgramControl(data){
  programSnapshot=data;
  document.querySelector('#programParticipantId').value=data.profile.id;
  document.querySelector('#programParticipantName').textContent=data.profile.name;
  document.querySelector('#programParticipantEmail').textContent=data.profile.email;
  document.querySelector('#customerProfileName').value=data.profile.name||'';
  document.querySelector('#customerProfileEmail').value=data.profile.email||'';
  document.querySelector('#customerBirthDate').value=data.profile.birth_date||'';
  document.querySelector('#customerStreet').value=data.profile.street||'';
  document.querySelector('#customerPostalCode').value=data.profile.postal_code||'';
  document.querySelector('#customerCity').value=data.profile.city||'';
  document.querySelector('#customerCountry').value=data.profile.country||'Deutschland';
  document.querySelector('#customerPhone').value=data.profile.phone||'';
  document.querySelector('#customerMobilePhone').value=data.profile.mobile_phone||'';
  document.querySelector('#customerWhatsappPhone').value=data.profile.whatsapp_phone||'';
  document.querySelector('#customerWhatsappSame').checked=data.profile.whatsapp_same_as_mobile===true;
  document.querySelector('#customerWhatsappPhone').disabled=data.profile.whatsapp_same_as_mobile===true;
  document.querySelector('#customerPreferredChannel').value=data.profile.preferred_communication_channel||'email';
  document.querySelector('#customerPostalActive').checked=data.profile.postal_mail_active!==false;
  document.querySelector('#customerPostalState').textContent=data.profile.postal_mail_active!==false?'Postanschrift aktiv':'Postanschrift inaktiv';
  document.querySelector('#programStartDate').value=data.access.programStartDate||new Date().toISOString().slice(0,10);
  document.querySelector('#programStatus').value=data.access.status;
  document.querySelector('#programCurrentWeek').value=String(data.progress.current_week||0);
  document.querySelector('#programCalculatedWeek').textContent=data.access.status==='paused'?'Kunde pausiert · kein Wochenzugriff':`Aktuell zugänglich: ${data.access.unlockedWeeks.length?data.access.unlockedWeeks.map(week=>`W${week}`).join(', '):'keine Woche'}`;
  document.querySelector('#programAccessBadge').textContent='Automatisch · 7 Tage';
  const grouped=Object.groupBy?Object.groupBy(data.gates,gate=>gate.week):data.gates.reduce((result,gate)=>{(result[gate.week]||=[]).push(gate);return result;},{});
  document.querySelector('#programGateList').innerHTML=Object.entries(grouped).map(([week,gates])=>`<div class="gate-correction-week"><strong>${Number(week)===0?'Onboarding':`Woche ${week}`}</strong>${gates.map(gate=>`<label><input type="checkbox" data-correction-gate="${gate.id}" data-original="${Boolean(gate.completed_at)}" ${gate.completed_at?'checked':''}> ${escapeHtml(gate.label)}</label>`).join('')}</div>`).join('');
  const confirmations=data.technicalConfirmations||[];
  const reached=confirmations.filter(item=>item.status!=='not_reached');
  document.querySelector('#technicalConfirmationList').innerHTML=reached.length?reached.map(item=>item.status==='confirmed'
    ?`<article class="technical-confirmation confirmed"><div><span>Woche ${item.week}</span><strong>✓ ${escapeHtml(item.title)}</strong><small>Bestätigt ${item.confirmation?.confirmedAt?new Date(item.confirmation.confirmedAt).toLocaleString('de-DE'):''}</small></div>${item.confirmation?.resultReference?`<p>Referenz: ${escapeHtml(item.confirmation.resultReference)}</p>`:''}</article>`
    :`<article class="technical-confirmation pending" data-technical-card><div><span>Woche ${item.week} · wartet auf Admin-Prüfung</span><strong>${escapeHtml(item.title)}</strong><small>Der Kunde kann diesen Schritt nicht selbst freischalten.</small></div><label>Ergebnis / Referenz<input data-technical-reference placeholder="z. B. Bericht-ID, Termin oder Ablageort"></label><label>Prüfvermerk<textarea data-technical-note rows="3" placeholder="Was wurde geprüft und bestätigt?"></textarea></label><button type="button" class="primary" data-confirm-technical data-week="${item.week}" data-step-id="${escapeHtml(item.stepId)}">Geprüft und sicher bestätigen</button></article>`).join('')
    :'<div class="technical-empty">Aktuell wartet kein externer Journey-Schritt auf eine Admin-Bestätigung.</div>';
}

document.querySelector('#technicalConfirmationList').addEventListener('click',async event=>{
  const button=event.target.closest('[data-confirm-technical]');
  if(!button)return;
  const card=button.closest('[data-technical-card]');
  const note=card.querySelector('[data-technical-note]').value.trim();
  const resultReference=card.querySelector('[data-technical-reference]').value.trim();
  if(note.length<5)return toast('Bitte einen nachvollziehbaren Prüfvermerk eingeben.');
  if(!confirm(`Technisches Ergebnis „${card.querySelector('strong').textContent}“ verbindlich bestätigen?`))return;
  button.disabled=true;
  try{
    const response=await fetch('/api/program-control',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({participantId:document.querySelector('#programParticipantId').value,technicalConfirmation:{week:Number(button.dataset.week),stepId:button.dataset.stepId,note,resultReference}})});
    const data=await response.json();
    if(!response.ok)throw new Error(data.error);
    renderProgramControl(data);
    toast('Technisches Ergebnis wurde auditierbar bestätigt.');
    await loadParticipants();
  }catch(error){toast(error.message);button.disabled=false;}
});
async function openProgramControl(participantId){if(!participantId)return;programDialog.showModal();document.querySelector('#programParticipantName').textContent='Wird geladen …';try{const response=await fetch(`/api/program-control?participantId=${encodeURIComponent(participantId)}`);const data=await response.json();if(!response.ok)throw new Error(data.error);renderProgramControl(data);}catch(error){programDialog.close();toast(error.message);}}
document.querySelector('#resetParticipantToOnboarding').addEventListener('click',async()=>{const id=document.querySelector('#programParticipantId').value;if(!id)return;if(!confirm('Möchtest du diesen Kunden wirklich auf den Onboarding-Start zurücksetzen?'))return;try{const response=await fetch('/api/program-control',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({participantId:id,resetToOnboarding:true})});const data=await response.json();if(!response.ok)throw new Error(data.error);renderProgramControl(data);programDialog.close();toast('Kunde wurde auf Onboarding zurückgesetzt.');await loadParticipants();}catch(error){toast(error.message);}});
