function renderSalesCallCard(lead){const answers=lead.qualification_answers||{},answered=Array.from({length:6},(_,index)=>answers[`q${index+1}`]).filter(value=>String(value||'').trim()).length;const completed=lead.status==='consultation'||['offer','customer'].includes(lead.status);document.querySelector('#leadSalesCallStatus').textContent=completed?'Gespräch geführt':lead.appointment_start?'Termin geplant':'Noch nicht geplant';document.querySelector('#leadSalesCallOverview').innerHTML=`<div><span>${lead.appointment_start?'✓':'○'}</span><p><b>Termin</b><small>${lead.appointment_start?crmDate(lead.appointment_start):'Noch nicht geplant'}</small></p></div><div><span>${answered===6?'✓':answered}</span><p><b>Gesprächsleitfaden</b><small>${answered} von 6 Antworten dokumentiert</small></p></div><div><span>${completed?'✓':'○'}</span><p><b>Abschlussentscheidung</b><small>${completed?'Gespräch abgeschlossen':'Noch offen'}</small></p></div>`;}
function renderLeadDashboard(data){activeLeadDashboard=data;const lead=data.lead,initials=lead.name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();document.querySelector('#leadDashboardInitials').textContent=initials;document.querySelector('#leadDashboardName').textContent=lead.name;document.querySelector('#leadDashboardStatus').textContent=leadStatusLabels[lead.status]||lead.status;document.querySelector('#leadDashboardContact').textContent=`${lead.email} · ${lead.phone||'keine Telefonnummer'}`;document.querySelector('#leadDashboardConvert').textContent=lead.converted_user_profile_id?'Teilnehmerkonto verwalten →':'Vertragsabschluss erfassen →';const signed=(data.contracts||[]).some(item=>item.status==='signed'&&item.document_confirmed_at&&item.video_contract_confirmed_at);const stageByStatus={new:0,contacted:1,scheduled:2,consultation:3,offer:4,later:0,customer:6,lost:0};let current=stageByStatus[lead.status]??0;if(signed&&current<5)current=5;const stages=[['Anfrage','Eingegangen'],['Kontakt','Qualifizieren'],['Termin','Erstgespräch'],['Gespräch','Bedarf klar'],['Angebot','Entscheidung'],['Vertrag','Dokument + Video'],['Teilnehmer','8 Wochen']];document.querySelector('#leadSalesProgressCount').textContent=`Schritt ${current+1} von 7`;document.querySelector('#leadProgressTrack').innerHTML=stages.map(([title,copy],index)=>`<div class="lead-progress-step ${index<current?'done':index===current?'current':''}"><span>${index<current?'✓':index+1}</span><b>${title}</b><small>${copy}</small></div>`).join('');document.querySelector('#leadContactDetails').innerHTML=`<dl class="lead-detail-list"><div><dt>E-Mail</dt><dd>${escapeHtml(lead.email)}</dd></div><div><dt>Telefon</dt><dd>${escapeHtml(lead.phone||'Nicht hinterlegt')}</dd></div><div><dt>Quelle</dt><dd>${escapeHtml(lead.utm_source||lead.source||'Unbekannt')}</dd></div><div><dt>Anfrage</dt><dd>${escapeHtml(lead.challenge||'Nicht beschrieben')}</dd></div><div><dt>Eingang</dt><dd>${crmDate(lead.created_at)}</dd></div></dl>`;document.querySelector('#leadOpenBalance').textContent=euro(data.finance.openBalance);document.querySelector('#leadBalanceState').textContent=data.finance.openBalance>0?'Zahlung oder Restbetrag noch offen':'Keine offenen Forderungen';document.querySelector('#leadBalanceDetails').innerHTML=`<div><dt>Unterzeichnete Verträge</dt><dd>${euro(data.finance.contractTotal)}</dd></div><div><dt>Gebuchte Zahlungen</dt><dd>${euro(data.finance.paidTotal)}</dd></div>`;document.querySelector('#leadCommunicationList').innerHTML=data.communications.length?data.communications.map(item=>`<article><div><strong>${escapeHtml(item.subject)}</strong><span>${communicationLabels[item.direction]||item.direction}</span></div><p>${escapeHtml(item.preview||'Kein Vorschautext')}</p><small>${crmDate(item.occurred_at)}</small></article>`).join(''):'<div class="lead-empty">Noch kein E-Mail-Verkehr protokolliert. Termin- und Zugangsmails erscheinen hier automatisch.</div>';document.querySelector('#leadContractList').innerHTML=data.contracts.length?data.contracts.map(item=>`<article class="${item.status}"><div><strong>${escapeHtml(item.title)}</strong><span>${contractStatusLabels[item.status]||item.status}</span></div><p>${euro(item.amount)}${item.contract_number?` · ${escapeHtml(item.contract_number)}`:''}</p><div class="lead-contract-checks"><i class="${item.document_confirmed_at?'ok':''}">${item.document_confirmed_at?'✓':'○'} Vertragsdokument</i><i class="${item.video_contract_confirmed_at?'ok':''}">${item.video_contract_confirmed_at?'✓':'○'} Videovertrag</i></div><small>${item.signed_at?`Unterzeichnet ${crmDate(item.signed_at)}`:`Angelegt ${crmDate(item.created_at)}`}</small></article>`).join(''):'<div class="lead-empty">Noch kein Vertrag angelegt.</div>';document.querySelector('#leadNotesText').textContent=lead.internal_notes||'Noch keine internen Notizen vorhanden.';const bank=data.bankAccount;document.querySelector('#leadBankDetails').innerHTML=bank?`<div><dt>Kontoinhaber</dt><dd>${escapeHtml(bank.account_holder||'—')}</dd></div><div><dt>IBAN</dt><dd>${escapeHtml(bank.iban||'—')}</dd></div><div><dt>BIC</dt><dd>${escapeHtml(bank.bic||'—')}</dd></div><div><dt>Verwendungszweck</dt><dd>${escapeHtml(bank.payment_reference||'—')}</dd></div>`:'<div><dt>Status</dt><dd>Noch nicht hinterlegt</dd></div>';const next=[];if(!lead.appointment_start)next.push('Erstgespräch mit dem Interessenten planen');if(!data.contracts.length)next.push('Passenden Vertrag anlegen und versenden');else if(!signed&&!lead.converted_user_profile_id)next.push('Vertragsdokument und Videovertrag vollständig bestätigen');if(data.finance.openBalance>0)next.push(`${euro(data.finance.openBalance)} Zahlungseingang abgleichen`);if(!bank)next.push('Bankverbindung und Verwendungszweck hinterlegen');if(data.questions.some(item=>item.status==='open'))next.push(`${data.questions.filter(item=>item.status==='open').length} Kundenfrage(n) beantworten`);if(!next.length)next.push('Akte ist vollständig – nächsten persönlichen Kontakt planen');document.querySelector('#leadNextSteps').innerHTML=next.slice(0,4).map((item,index)=>`<div><span>${index+1}</span><p>${escapeHtml(item)}</p></div>`).join('');renderLeadTasks();renderSalesCallCard(lead);}
async function loadLeadDashboard(id=activeLeadDashboard?.lead?.id){if(!id)return;const response=await fetch(`/api/leads?action=dashboard&id=${encodeURIComponent(id)}`),data=await response.json();if(!response.ok)throw new Error(data.error);renderLeadDashboard(data);}
async function openLeadDashboard(id){document.querySelector('#leadListView').classList.add('hidden');document.querySelector('#leadDashboard').classList.remove('hidden');document.querySelector('#leadDashboardName').textContent='Akte wird geladen …';try{await loadLeadDashboard(id);renderContextNavigation('leads');window.scrollTo({top:0,behavior:'smooth'});}catch(error){document.querySelector('#leadListView').classList.remove('hidden');document.querySelector('#leadDashboard').classList.add('hidden');toast(error.message);}}
function resetLeadListView(){activeLeadDashboard=null;document.querySelector('#leadDashboard').classList.add('hidden');document.querySelector('#leadListView').classList.remove('hidden');}
function closeLeadDashboard(){resetLeadListView();renderLeadRows();renderContextNavigation('leads');}
const leadRecordDialog=document.querySelector('#leadRecordDialog'),leadRecordForm=document.querySelector('#leadRecordForm');
const recordDefinitions={contract:{title:'Vertragsabschluss erfassen',copy:'Nur ein unterschriebener Vertrag mit Vertragsdokument und Videovertrag erzeugt automatisch einen Teilnehmer.',fields:`<label class="wide">Vertragsbezeichnung<input name="title" required placeholder="Finde dein Ding · 8-Wochen-Programm"></label><label>Vertragsnummer<input name="contractNumber" placeholder="FDD-2026-001"></label><label>Betrag in Euro<input name="amount" type="number" min="0" step="0.01" required></label><label>Status<select name="status"><option value="draft">Entwurf</option><option value="sent">Versendet</option><option value="signed">Unterschrieben</option><option value="cancelled">Storniert</option></select></label><label>Programmstart<input name="programStartDate" type="date" required></label><fieldset class="wide lead-contract-confirmations"><legend>Verbindliche Abschlussnachweise</legend><label><input name="documentConfirmed" type="checkbox" value="true"> Vertragsdokument vollständig unterzeichnet</label><label><input name="videoContractConfirmed" type="checkbox" value="true"> Videovertrag vollständig durchgeführt</label></fieldset>`},payment:{title:'Zahlungseingang erfassen',copy:'Der gebuchte Betrag wird mit dem Vertragsvolumen abgeglichen.',fields:`<label>Betrag in Euro<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Buchungsdatum<input name="bookedAt" type="date" required></label><label class="wide">Verwendungszweck / Referenz<input name="reference" placeholder="FDD-2026-001"></label>`},communication:{title:'E-Mail protokollieren',copy:'Manueller Eintrag für den nachvollziehbaren Kommunikationsverlauf.',fields:`<label>Richtung<select name="direction"><option value="outbound">Ausgang</option><option value="inbound">Eingang</option><option value="system">System</option></select></label><label class="wide">Betreff<input name="subject" required></label><label class="wide">Vorschau<textarea name="preview"></textarea></label>`},task:{title:'Aufgabe anlegen',copy:'Interne Aufgaben stehen gemeinsam mit den Fragen aus dem Kundenprozess.',fields:`<label class="wide">Aufgabe<input name="title" required></label><label>Fällig am<input name="dueAt" type="date"></label><label class="wide">Details<textarea name="details"></textarea></label>`},bank:{title:'Bankverbindung bearbeiten',copy:'Die Daten dienen dem manuellen Abgleich eingehender Überweisungen.',fields:`<label class="wide">Kontoinhaber<input name="accountHolder"></label><label class="wide">IBAN<input name="iban"></label><label>BIC<input name="bic"></label><label class="wide">Verwendungszweck<input name="paymentReference"></label>`},note:{title:'Interne Notizen bearbeiten',copy:'Diese Notizen sind ausschließlich für Administratoren sichtbar.',fields:`<label class="wide">Notizen<textarea name="notes"></textarea></label>`}};
function openLeadRecord(type){const definition=recordDefinitions[type];if(!definition||!activeLeadDashboard)return;leadRecordForm.reset();leadRecordForm.elements.recordType.value=type;document.querySelector('#leadRecordTitle').textContent=definition.title;document.querySelector('#leadRecordCopy').textContent=definition.copy;document.querySelector('#leadRecordFields').innerHTML=definition.fields;if(type==='payment')leadRecordForm.elements.bookedAt.value=browserDateKey();if(type==='contract')leadRecordForm.elements.programStartDate.value=browserDateKey();if(type==='note')leadRecordForm.elements.notes.value=activeLeadDashboard.lead.internal_notes||'';if(type==='bank'&&activeLeadDashboard.bankAccount){const bank=activeLeadDashboard.bankAccount;leadRecordForm.elements.accountHolder.value=bank.account_holder||'';leadRecordForm.elements.iban.value=bank.iban||'';leadRecordForm.elements.bic.value=bank.bic||'';leadRecordForm.elements.paymentReference.value=bank.payment_reference||'';}leadRecordDialog.showModal();}
async function saveLeadDashboardRecord(payload){const id=activeLeadDashboard?.lead?.id;if(!id)throw new Error('Keine Interessentenakte geöffnet.');const response=await fetch('/api/leads?action=dashboard-record',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,...payload})}),data=await response.json();if(!response.ok)throw new Error(data.error);await loadLeadDashboard(id);return data;}
document.querySelector('#closeLeadDashboard').addEventListener('click',closeLeadDashboard);document.querySelector('#editLeadProfile').addEventListener('click',()=>openLeadEditor(activeLeadDashboard?.lead?.id));document.querySelector('#openLeadSalesCall').addEventListener('click',()=>openLeadEditor(activeLeadDashboard?.lead?.id));document.querySelector('#leadDashboardConvert').addEventListener('click',()=>activeLeadDashboard?.lead?.converted_user_profile_id?openLeadEditor(activeLeadDashboard.lead.id):openLeadRecord('contract'));document.querySelectorAll('[data-lead-edit="profile"]').forEach(button=>button.addEventListener('click',()=>openLeadEditor(activeLeadDashboard?.lead?.id)));document.querySelectorAll('[data-lead-record]').forEach(button=>button.addEventListener('click',()=>openLeadRecord(button.dataset.leadRecord)));document.querySelectorAll('[data-close-lead-record]').forEach(button=>button.addEventListener('click',()=>leadRecordDialog.close()));document.querySelectorAll('[data-lead-task-filter]').forEach(button=>button.addEventListener('click',()=>{leadTaskFilter=button.dataset.leadTaskFilter;document.querySelectorAll('[data-lead-task-filter]').forEach(item=>item.classList.toggle('active',item===button));renderLeadTasks();}));leadRecordForm.addEventListener('submit',async event=>{event.preventDefault();const button=leadRecordForm.querySelector('[type="submit"]');button.disabled=true;try{const payload=Object.fromEntries(new FormData(leadRecordForm));const result=await saveLeadDashboardRecord(payload);leadRecordDialog.close();if(payload.recordType==='communication')await loadCommunications();if(result.participantActivated){await Promise.all([loadParticipants(),loadLeads(),loadUsers(),loadCommunications()]);openParticipantLogin(result.participant.profileId,result.participant.oneTimePassword||'');toast('Vertrag abgeschlossen: Teilnehmer-Login und Einmalzugang wurden automatisch erstellt.');}else toast('Akte wurde aktualisiert.');}catch(error){toast(error.message);}finally{button.disabled=false;}});
async function saveLead(showMessage=true){const response=await fetch('/api/leads?action=update',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(leadPayload())});const data=await response.json();if(!response.ok)throw new Error(data.error);updateLeadCache(data.lead);renderLeadDialog(data.lead);if(showMessage)toast('Interessent wurde gespeichert.');return data.lead;}
leadForm.addEventListener('submit',async event=>{event.preventDefault();try{await saveLead();await loadLeads();if(activeLeadDashboard)await loadLeadDashboard();}catch(error){toast(error.message);}});
document.querySelector('#refreshSlots').addEventListener('click',loadAvailableSlots);
document.querySelector('#slotRangeStart').addEventListener('change',loadAvailableSlots);
leadForm.elements.appointmentDuration.addEventListener('change',()=>{leadForm.elements.appointmentStart.value='';showSelectedSlot('');loadAvailableSlots();});
document.querySelector('#scheduleLead').addEventListener('click',async()=>{const button=document.querySelector('#scheduleLead'),start=leadForm.elements.appointmentStart.value,duration=Number(leadForm.elements.appointmentDuration.value);if(!start)return toast('Bitte einen angezeigten freien Termin auswählen.');button.disabled=true;try{const saved=await saveLead(false);const response=await fetch('/api/leads?action=schedule',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:saved.id,start:new Date(start).toISOString(),duration})});const data=await response.json();if(!response.ok)throw new Error(data.error);updateLeadCache(data.lead);renderLeadDialog(data.lead);toast('Kalendertermin und Google Meet wurden erstellt.');await loadLeads();if(activeLeadDashboard)await loadLeadDashboard();}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.querySelector('#cancelLeadAppointment').addEventListener('click',async()=>{if(!confirm('Termin wirklich absagen? Google informiert den eingeladenen Interessenten.'))return;try{const response=await fetch('/api/leads?action=cancel-appointment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:leadForm.elements.id.value})});const data=await response.json();if(!response.ok)throw new Error(data.error);updateLeadCache(data.lead);renderLeadDialog(data.lead);toast('Termin wurde abgesagt.');await loadLeads();if(activeLeadDashboard)await loadLeadDashboard();}catch(error){toast(error.message);}});
const systemStatusLabels={active:'Aktiv',ready:'Bereit zur Verbindung',missing:'Konfiguration fehlt',planned:'Geplant'};
function systemStatusBadge(item){const key=item.status?.key||'missing';return `<span class="system-status-badge ${escapeHtml(item.status?.tone||'danger')}"><i></i>${escapeHtml(item.status?.label||systemStatusLabels[key]||key)}</span>`;}
function renderIntegrationRegistry(items=[]){const grid=document.querySelector('#integrationStatusGrid');if(!grid)return;grid.innerHTML=items.length?items.map(item=>`<article class="system-registry-card ${escapeHtml(item.status?.tone||'neutral')}"><div class="system-registry-head"><span class="system-tool-icon tool-${escapeHtml(item.id)}">${escapeHtml(item.icon)}</span>${systemStatusBadge(item)}</div><small>${escapeHtml(item.category)}</small><h4>${escapeHtml(item.name)}</h4><p>${escapeHtml(item.purpose)}</p><div class="system-detail">${escapeHtml(item.detail)}</div>${item.action==='google-connect'?`<button class="secondary system-connect-action" type="button" data-system-action="google-connect">${item.status?.key==='active'?'Google neu verbinden':'Google verbinden'}</button>`:''}</article>`).join(''):'<div class="empty">Keine Schnittstellen registriert.</div>';}
function renderAgentRegistry(items=[]){const grid=document.querySelector('#agentStatusGrid');if(!grid)return;grid.innerHTML=items.length?items.map(item=>`<article class="agent-registry-card ${escapeHtml(item.status?.tone||'neutral')}"><div class="agent-registry-top"><span class="agent-avatar">${escapeHtml(item.icon)}</span><div><small>${escapeHtml(item.phase)}</small><h4>${escapeHtml(item.name)}</h4></div>${systemStatusBadge(item)}</div><p>${escapeHtml(item.situation)}</p><dl><div><dt>Werkzeug</dt><dd>${escapeHtml(item.tool)}</dd></div><div><dt>Betriebshinweis</dt><dd>${escapeHtml(item.detail)}</dd></div></dl></article>`).join(''):'<div class="empty">Keine KI-Agenten registriert.</div>';}
async function loadSystemStatus(){const refresh=document.querySelector('#systemStatusRefresh');if(refresh)refresh.disabled=true;try{const response=await fetch('/api/leads?action=system-status'),data=await response.json();if(!response.ok)throw new Error(data.error);renderIntegrationRegistry(data.integrations);renderAgentRegistry(data.agents);document.querySelector('#activeIntegrationCount').textContent=`${data.summary.activeIntegrations} / ${data.summary.totalIntegrations}`;document.querySelector('#activeAgentCount').textContent=`${data.summary.activeAgents} / ${data.summary.totalAgents}`;document.querySelector('#plannedSystemCount').textContent=String(data.summary.planned);document.querySelector('#systemCheckedAt').textContent=new Date(data.checkedAt).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'});const connected=data.integrations.filter(item=>item.status.key==='active').length;document.querySelector('#integrationRegistryState').textContent=`${connected} aktiv`;document.querySelector('#integrationRegistryState').classList.toggle('active',connected>0);const activeAgents=data.agents.filter(item=>item.status.key==='active').length;document.querySelector('#agentRegistryState').textContent=`${activeAgents} aktiv`;document.querySelector('#agentRegistryState').classList.toggle('active',activeAgents>0);}catch(error){const message=escapeHtml(error.message||'Systemstatus konnte nicht geladen werden.');document.querySelector('#integrationStatusGrid').innerHTML=`<div class="empty system-error">${message}</div>`;document.querySelector('#agentStatusGrid').innerHTML=`<div class="empty system-error">${message}</div>`;document.querySelector('#integrationRegistryState').textContent='Prüfung fehlgeschlagen';document.querySelector('#agentRegistryState').textContent='Prüfung fehlgeschlagen';}finally{if(refresh)refresh.disabled=false;}}
document.querySelector('#systemStatusRefresh')?.addEventListener('click',loadSystemStatus);
document.querySelector('#integrationStatusGrid')?.addEventListener('click',event=>{if(event.target.closest('[data-system-action="google-connect"]'))location.href='/api/google/connect';});

const communicationDirectionLabels={inbound:'Posteingang',outbound:'Ausgang',system:'System'};
const communicationDeliveryLabels={draft:'Entwurf',logged:'Dokumentiert',sent:'Versendet',received:'Empfangen',system:'System',failed:'Fehlgeschlagen'};
function communicationTime(value,long=false){const date=new Date(value);if(Number.isNaN(date.getTime()))return'—';return long?date.toLocaleString('de-DE',{dateStyle:'medium',timeStyle:'short'}):date.toLocaleDateString('de-DE')===new Date().toLocaleDateString('de-DE')?date.toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'}):date.toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'});}
function communicationFiltered(){const query=(document.querySelector('#communicationSearch')?.value||'').trim().toLowerCase();return communications.filter(item=>{const inFolder=communicationFolder==='all'||communicationFolder==='draft'&&item.delivery_status==='draft'||communicationFolder==='system'&&(item.direction==='system'||item.delivery_status==='system')||communicationFolder==='inbound'&&item.direction==='inbound'||communicationFolder==='outbound'&&item.direction==='outbound'&&item.delivery_status!=='draft';const haystack=`${item.contact?.name||''} ${item.contact?.email||''} ${item.subject||''} ${item.body||item.preview||''}`.toLowerCase();return inFolder&&(!query||haystack.includes(query));});}
function renderCommunicationReading(){const pane=document.querySelector('#communicationReadingPane');if(!pane)return;const item=communications.find(message=>message.id===activeCommunicationId);if(!item){pane.innerHTML='<div class="mail-reading-empty"><span>✉</span><h2>Nachricht auswählen</h2><p>Öffne links eine Nachricht, um den vollständigen Verlauf und die zugehörige CRM-Akte zu sehen.</p></div>';return;}const contact=item.contact||{};const status=communicationDeliveryLabels[item.delivery_status]||'Dokumentiert';pane.innerHTML=`<div class="mail-reading-head"><div class="mail-reading-labels"><span class="mail-direction ${escapeHtml(item.direction)}">${escapeHtml(communicationDirectionLabels[item.direction]||item.direction)}</span><span class="mail-contact-type">${contact.type==='customer'?'Teilnehmer':'Interessent'}</span><span class="mail-contact-type">${escapeHtml(status)}</span></div><h2>${escapeHtml(item.subject||'Ohne Betreff')}</h2><div class="mail-sender"><span class="mail-contact-avatar">${escapeHtml((contact.name||'?').split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase())}</span><div><strong>${escapeHtml(contact.name||'Unbekannter Kontakt')}</strong><small>${escapeHtml(contact.email||'Keine E-Mail hinterlegt')}</small></div><time>${escapeHtml(communicationTime(item.occurred_at,true))}</time></div></div><div class="mail-reading-body">${escapeHtml(item.body||item.preview||'Kein Nachrichtentext hinterlegt.')}</div><div class="mail-reading-actions"><button class="primary" type="button" data-reply-communication="${escapeHtml(item.lead_id)}">Antwort vorbereiten</button><button class="secondary" type="button" data-open-communication-contact="${escapeHtml(item.lead_id)}">CRM-Akte öffnen →</button></div>`;pane.querySelector('[data-reply-communication]')?.addEventListener('click',()=>openCommunicationComposer(item.lead_id,item.subject));pane.querySelector('[data-open-communication-contact]')?.addEventListener('click',()=>{showView('leads');openLeadDashboard(item.lead_id);});}
function renderCommunicationList(){const list=document.querySelector('#communicationList');if(!list)return;const filtered=communicationFiltered();if(activeCommunicationId&&!filtered.some(item=>item.id===activeCommunicationId))activeCommunicationId=null;if(!activeCommunicationId&&filtered.length)activeCommunicationId=filtered[0].id;list.innerHTML=filtered.length?filtered.map(item=>{const contact=item.contact||{},unread=item.direction==='inbound'&&!item.read_at;return `<button class="mail-list-item ${item.id===activeCommunicationId?'active':''} ${unread?'unread':''}" type="button" data-communication-id="${escapeHtml(item.id)}"><div class="mail-item-top"><span class="mail-contact-avatar">${escapeHtml((contact.name||'?').split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase())}</span><div class="mail-item-contact"><strong>${escapeHtml(contact.name||'Unbekannter Kontakt')}</strong><small>${escapeHtml(contact.email||'')}</small></div><time>${escapeHtml(communicationTime(item.occurred_at))}</time></div><h3>${escapeHtml(item.subject||'Ohne Betreff')}</h3><p>${escapeHtml(item.body||item.preview||'Kein Nachrichtentext')}</p><div class="mail-item-meta"><span class="mail-direction ${escapeHtml(item.direction)}">${escapeHtml(communicationDirectionLabels[item.direction]||item.direction)}</span><span class="mail-contact-type">${contact.type==='customer'?'Teilnehmer':'Interessent'}</span>${item.delivery_status==='draft'?'<span class="mail-contact-type">Entwurf</span>':''}</div></button>`;}).join(''):'<div class="empty">In diesem Ordner wurden keine Nachrichten gefunden.</div>';list.querySelectorAll('[data-communication-id]').forEach(button=>button.addEventListener('click',()=>selectCommunication(button.dataset.communicationId)));renderCommunicationReading();}
function updateCommunicationSummary(summary={}){document.querySelector('#communicationTotal').textContent=String(summary.total||0);document.querySelector('#communicationUnread').textContent=String(summary.unread||0);document.querySelector('#communicationCustomers').textContent=String(summary.customers||0);document.querySelector('#communicationLeads').textContent=String(summary.leads||0);document.querySelector('#mailAllCount').textContent=String(summary.total||0);document.querySelector('#mailInboxCount').textContent=String(summary.inbox||0);document.querySelector('#mailSentCount').textContent=String(summary.sent||0);document.querySelector('#mailDraftCount').textContent=String(summary.drafts||0);document.querySelector('#mailSystemCount').textContent=String(communications.filter(item=>item.direction==='system'||item.delivery_status==='system').length);document.querySelector('#communicationNavCount').textContent=String(summary.unread||0);}
function localCommunicationSummary(){return{total:communications.length,inbox:communications.filter(item=>item.direction==='inbound').length,unread:communications.filter(item=>item.direction==='inbound'&&!item.read_at).length,sent:communications.filter(item=>item.direction==='outbound'&&item.delivery_status!=='draft').length,drafts:communications.filter(item=>item.delivery_status==='draft').length,customers:new Set(communications.filter(item=>item.contact?.type==='customer').map(item=>item.lead_id)).size,leads:new Set(communications.filter(item=>item.contact?.type==='lead').map(item=>item.lead_id)).size};}
function setCommunicationFolder(folder='all'){communicationFolder=folder;document.querySelectorAll('[data-mail-folder]').forEach(button=>button.classList.toggle('active',button.dataset.mailFolder===folder));renderCommunicationList();}
async function selectCommunication(id){activeCommunicationId=id;const item=communications.find(message=>message.id===id);if(item?.direction==='inbound'&&!item.read_at){item.read_at=new Date().toISOString();updateCommunicationSummary(localCommunicationSummary());fetch('/api/leads?action=communication-read',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})}).catch(()=>{});}renderCommunicationList();}
async function loadCommunications(){const refresh=document.querySelector('#refreshCommunications');if(refresh)refresh.disabled=true;try{const response=await fetch('/api/leads?action=communications'),data=await response.json();if(!response.ok)throw new Error(data.error);communications=data.communications||[];communicationContacts=data.contacts||[];updateCommunicationSummary(data.summary||{});renderCommunicationList();renderCommunicationRecipients();}catch(error){document.querySelector('#communicationList').innerHTML=`<div class="empty system-error">${escapeHtml(error.message||'Kommunikation konnte nicht geladen werden.')}</div>`;}finally{if(refresh)refresh.disabled=false;}}
function renderCommunicationRecipients(){const select=document.querySelector('#communicationRecipient');if(!select)return;const current=select.value;select.innerHTML='<option value="">Kontakt auswählen</option>'+communicationContacts.slice().sort((a,b)=>a.name.localeCompare(b.name,'de')).map(contact=>`<option value="${escapeHtml(contact.id)}">${escapeHtml(contact.name)} · ${contact.type==='customer'?'Teilnehmer':'Interessent'} · ${escapeHtml(contact.email)}</option>`).join('');if(communicationContacts.some(contact=>contact.id===current))select.value=current;}
const communicationComposerDialog=document.querySelector('#communicationComposerDialog'),communicationComposerForm=document.querySelector('#communicationComposerForm');
function openCommunicationComposer(leadId='',previousSubject=''){renderCommunicationRecipients();communicationComposerForm.reset();if(leadId)communicationComposerForm.elements.leadId.value=leadId;if(previousSubject)communicationComposerForm.elements.subject.value=/^Re:/i.test(previousSubject)?previousSubject:`Re: ${previousSubject}`;communicationComposerDialog.showModal();requestAnimationFrame(()=>leadId?communicationComposerForm.elements.subject.focus():communicationComposerForm.elements.leadId.focus());}
document.querySelector('#openCommunicationComposer').addEventListener('click',()=>openCommunicationComposer());
document.querySelectorAll('[data-close-communication-composer]').forEach(button=>button.addEventListener('click',()=>communicationComposerDialog.close()));
document.querySelectorAll('[data-mail-folder]').forEach(button=>button.addEventListener('click',()=>setCommunicationFolder(button.dataset.mailFolder)));
document.querySelector('#communicationSearch').addEventListener('input',renderCommunicationList);
document.querySelector('#refreshCommunications').addEventListener('click',loadCommunications);
document.querySelector('[data-open-mail-settings]').addEventListener('click',()=>{showView('settings');showSettingsPanel('integrations');});
communicationComposerForm.addEventListener('submit',async event=>{event.preventDefault();const button=communicationComposerForm.querySelector('[type="submit"]');button.disabled=true;try{const payload=Object.fromEntries(new FormData(communicationComposerForm));const response=await fetch('/api/leads?action=communication-draft',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.error);communicationComposerDialog.close();await loadCommunications();activeCommunicationId=data.record?.id||activeCommunicationId;renderCommunicationList();toast(data.message);}catch(error){toast(error.message);}finally{button.disabled=false;}});

function filteredLeadList(){const query=normalizeContactSearch(document.querySelector('#leadListSearch')?.value||'');return leads.filter(lead=>{if(lead.converted_user_profile_id||lead.status==='customer')return false;const inFilter=leadListFilter==='all'||leadListFilter==='active'&&!['lost','later'].includes(lead.status)||lead.status===leadListFilter;const matchesSearch=!query||normalizeContactSearch(collectContactSearchValues(lead).join(' ')).includes(query);return inFilter&&matchesSearch;});}
function renderLeadRows(){const definition=leadListDefinitions[leadListFilter]||leadListDefinitions.all,filtered=filteredLeadList(),rows=document.querySelector('#leadRows');document.querySelector('#leadListEyebrow').textContent=definition.eyebrow;document.querySelector('#leadListTitle').textContent=definition.title;document.querySelector('#leadListDescription').textContent=definition.description;document.querySelector('#leadListCount').textContent=`${filtered.length} ${filtered.length===1?'Interessent':'Interessenten'}`;rows.innerHTML=filtered.length?filtered.map(lead=>`<div class="table-data lead-row" data-lead-id="${escapeHtml(lead.id)}"><div class="participant"><span class="avatar">${escapeHtml(lead.name.slice(0,2).toUpperCase())}</span><div><strong>${escapeHtml(lead.name)}</strong><small>${escapeHtml(lead.email)}</small></div></div><span>${escapeHtml(lead.utm_source||lead.source||'Unbekannt')}</span><span>${escapeHtml(leadStatusLabels[lead.status]||lead.status)}</span><span>${new Date(lead.created_at).toLocaleDateString('de-DE')}</span><button class="lead-next" data-open-lead="${escapeHtml(lead.id)}">${lead.appointment_start?`${new Date(lead.appointment_start).toLocaleDateString('de-DE')} · ${new Date(lead.appointment_start).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}`:'Akte öffnen →'}</button></div>`).join(''):`<div class="empty">In „${escapeHtml(definition.title)}“ wurden keine passenden Interessenten gefunden.</div>`;rows.querySelectorAll('[data-open-lead]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();openLeadDashboard(button.dataset.openLead);}));rows.querySelectorAll('.lead-row').forEach(row=>row.addEventListener('click',()=>openLeadDashboard(row.dataset.leadId)));}
function setLeadListFilter(filter='all'){leadListFilter=leadListDefinitions[filter]?filter:'all';activeLeadDashboard=null;document.querySelector('#leadDashboard').classList.add('hidden');document.querySelector('#leadListView').classList.remove('hidden');renderLeadRows();renderContextNavigation('leads');document.querySelector('#leadListView').scrollIntoView({behavior:'smooth',block:'start'});}
async function loadLeads(){try{const response=await fetch('/api/leads');const data=await response.json();if(!response.ok)throw new Error(data.error);leads=data.leads;renderLeadRows();if(document.querySelector('.view.active')?.dataset.panel==='leads'&&!activeLeadDashboard)renderContextNavigation('leads');renderGlobalContactSearch();}catch(error){document.querySelector('#leadRows').innerHTML=`<div class="empty">${escapeHtml(error.message)}</div>`;}}
document.querySelector('#leadListSearch')?.addEventListener('input',renderLeadRows);
async function loadUsers(){try{const response=await fetch('/api/users');const data=await response.json();if(!response.ok)throw new Error(data.error);users=data.users;const permissionLabels={customer_portal:'Kundenportal',clara_program:'Clara',documents:'Dokumente',community:'Community',dashboard:'Dashboard',customers:'Kunden',leads:'Interessenten',sales_calls:'Gespräche',program:'8-Wochen-Prozess',communications:'Kommunikation',finance:'Finanzen',settings:'Einstellungen',users:'Benutzer'};document.querySelector('#userRows').innerHTML=users.length?users.map(user=>{const progress=user.participant_progress?.[0],internal=user.role==='admin';const access=internal?(user.staff_permissions||[]):(user.permissions||[]);return `<div class="table-data"><div class="participant"><span class="avatar">${escapeHtml(user.name.slice(0,2).toUpperCase())}</span><div><strong>${escapeHtml(user.name)}</strong><small>${escapeHtml(user.email)}</small></div></div><span class="user-meta"><b>${internal?escapeHtml(staffRoleLabels[user.staff_role]||'Interne Rolle'):'Kunde'}</b><small>${user.status==='active'?'Aktiv':'Deaktiviert'}</small></span><span class="access-tags">${access.slice(0,4).map(permission=>`<i>${escapeHtml(permissionLabels[permission]||permission)}</i>`).join('')||'<i>Keine Zugänge</i>'}${access.length>4?`<i>+${access.length-4}</i>`:''}</span><span class="user-meta"><b>${progress?`Woche ${progress.current_week}`:'—'}</b><small>${escapeHtml(progress?.program_status||(internal?'Mitarbeiterzugang':'Kein Programm'))}</small></span><button class="user-manage" data-edit-user="${escapeHtml(user.id)}">Bearbeiten →</button></div>`;}).join(''):'<div class="empty">Noch keine Benutzer vorhanden.</div>';document.querySelectorAll('[data-edit-user]').forEach(button=>button.addEventListener('click',()=>openUserEdit(button.dataset.editUser)));}catch(error){document.querySelector('#userRows').innerHTML=`<div class="empty">${escapeHtml(error.message)}</div>`;}}
document.querySelector('#logout').addEventListener('click',async()=>{await fetch('/api/auth?action=session',{method:'DELETE'});location.replace('/login');});
const adminParams=new URLSearchParams(location.search);
function applyStaffNavigation(session){const all=['dashboard','customers','leads','sales_calls','program','communications','finance','settings','users'],permissions=session?.staffPermissions?.length?session.staffPermissions:session?.role==='admin'&&!('staffPermissions' in (session||{}))?all:[];activeStaffPermissions=permissions;const byView={command:['dashboard'],participants:['customers','program','sales_calls'],leads:['leads'],communications:['communications'],clarity:['program'],gates:['program'],settings:['settings']};document.querySelectorAll('.sidebar [data-view]').forEach(button=>{button.hidden=!(byView[button.dataset.view]||[]).some(permission=>permissions.includes(permission));});return permissions;}
fetch('/api/auth?action=session').then(async response=>{if(!response.ok)return location.replace('/login');const sessionData=await response.json(),permissions=applyStaffNavigation(sessionData.user),legacyUsersView=adminParams.get('view')==='users'&&permissions.includes('users');const requested=legacyUsersView?'settings':adminParams.get('view'),allowedView=requested&&titles[requested]&&!document.querySelector(`[data-view="${requested}"]`)?.hidden?requested:'command';showView(allowedView);if(legacyUsersView)showSettingsPanel('users');else if(adminParams.get('section')&&permissions.includes('settings'))showSettingsPanel(adminParams.get('section'));if(adminParams.get('google')==='connected')toast('Google Calendar wurde erfolgreich verbunden.');else if(adminParams.get('google')==='error')toast('Google-Verbindung wurde abgebrochen.');if(location.search)history.replaceState(null,'',location.pathname);const jobs=[loadCommandDashboard()];if(permissions.some(item=>['customers','program','sales_calls'].includes(item)))jobs.push(loadParticipants());if(permissions.includes('leads'))jobs.push(loadLeads());if(permissions.includes('users'))jobs.push(loadUsers());if(permissions.includes('communications'))jobs.push(loadCommunications());if(permissions.includes('settings'))jobs.push(loadSystemStatus(),loadBookingSettings().catch(error=>toast(error.message)));if(permissions.some(item=>['settings','program'].includes(item)))jobs.push(loadGateSettings());await Promise.all(jobs);});renderParticipants();
